  ('acacacac-acac-4cac-8cac-000000000010', '22222222-2222-4222-8222-000000000001', 'abababab-abab-4bab-8bab-000000000004', 'Rudern im Sitzen, Theraband rot', 'Im Sitzen das rote Band heranziehen',
