  ('acacacac-acac-4cac-8cac-000000000013', '22222222-2222-4222-8222-000000000001', 'abababab-abab-4bab-8bab-000000000007', 'Vierfuesslerstand, Arm strecken', 'Im Vierfuessler einen Arm nach vorn strecken',
