-- katalog:anfang - erzeugt von scripts/katalog-sql.mjs (pnpm katalog:sql --schreiben), nicht von Hand aendern.
-- Der mitgelieferte Uebungskatalog (UEB-012, ANN-382), uebernommen wie per Knopf, mit
-- festen Kennungen. Ein Namenskonflikt mit den Uebungen oben bricht den Seed ab.
do $seed$
declare
  v_ergebnis jsonb;
begin
  v_ergebnis := app.import_exercise_catalog_for(
    '22222222-2222-4222-8222-000000000001',
    '11111111-1111-4111-8111-000000000001',
    $katalog$[
{"schluessel":"BT-01","version":"1.0.0","name":"Fußpumpe (Dorsal-/Plantarflexion)","alltagsname":"Füße auf und ab bewegen","region":"fuss","ziel":"mobilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":[20,30],"taeglich":3},"anleitung":["Legen Sie sich auf den Rücken, die Beine liegen ausgestreckt und locker.","Ziehen Sie beide Fußspitzen kräftig zu sich heran.","Strecken Sie die Fußspitzen danach weit vom Körper weg.","Bewegen Sie die Füße zügig im Wechsel und atmen Sie dabei ruhig weiter."],"fehler":["Die Bewegung bleibt klein, die Waden arbeiten kaum.","Die Luft wird angehalten."],"hinweise_praxis":"In Zeiten mit viel Bettruhe auch stündlich sinnvoll; die Häufigkeit dann im Plan eintragen."},
{"schluessel":"BT-02","version":"1.0.0","name":"Fußkreisen","alltagsname":"Füße kreisen","region":"fuss","ziel":"mobilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":10,"taeglich":3},"anleitung":["Legen Sie sich auf den Rücken, die Beine liegen ausgestreckt und locker.","Kreisen Sie beide Füße langsam und so weit, wie es geht.","Machen Sie 10 Kreise in die eine Richtung und danach 10 in die andere.","Die Beine bleiben dabei ruhig liegen, nur die Füße bewegen sich."],"fehler":["Die Kreise sind klein und eckig.","Das ganze Bein dreht mit."]},
{"schluessel":"BT-03","version":"1.0.0","name":"Quadrizepsanspannung, isometrisch","alltagsname":"Knie in die Unterlage drücken","region":"knie","ziel":"kraft","ausgangsstellung":"rueckenlage","hilfsmittel":["handtuch"],"niveau":1,"dosierung":{"wiederholungen":10,"halten_s":5,"je_seite":true,"taeglich":3},"anleitung":["Legen Sie sich auf den Rücken und legen Sie ein klein gerolltes Handtuch unter ein Knie.","Ziehen Sie die Fußspitze zu sich und drücken Sie die Kniekehle fest in das Handtuch.","Halten Sie die Spannung 5 Sekunden und atmen Sie dabei ruhig weiter.","Lassen Sie locker und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberschenkel bleibt locker, die Kniescheibe bewegt sich kaum.","Die Luft wird angehalten."]},
{"schluessel":"BT-04","version":"1.0.0","name":"Gesäßanspannung, isometrisch","alltagsname":"Po anspannen","region":"huefte","ziel":"kraft","ausgangsstellung":"rueckenlage","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":10,"halten_s":5,"taeglich":3},"anleitung":["Legen Sie sich auf den Rücken, die Beine liegen ausgestreckt.","Spannen Sie beide Pobacken fest an, als wollten Sie sie zusammendrücken.","Halten Sie die Spannung 5 Sekunden und atmen Sie dabei ruhig weiter.","Lassen Sie danach ganz locker und machen Sie eine kurze Pause."],"fehler":["Die Luft wird angehalten.","Der Rücken drückt sich ins Hohlkreuz."]},
{"schluessel":"BT-05","version":"1.0.0","name":"Fersengleiten (Kniebeugung in Rückenlage)","alltagsname":"Ferse zum Po schieben","region":"knie","ziel":"mobilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":["handtuch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"je_seite":true,"taeglich":3},"anleitung":["Legen Sie sich auf den Rücken und legen Sie ein Handtuch unter eine Ferse, damit sie leichter gleitet.","Schieben Sie die Ferse langsam auf der Unterlage Richtung Po, so weit es angenehm geht.","Schieben Sie das Bein danach langsam wieder lang.","Wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Die Ferse hebt von der Unterlage ab.","Das Knie kippt nach innen oder außen.","Das Bein wird mit Schwung bewegt."],"hinweise_praxis":"Nach Hüftendoprothese die Beugegrenze nach OP-Bericht und ärztlicher Vorgabe beachten."},
{"schluessel":"BT-06","version":"1.0.0","name":"Beinabspreizen in Rückenlage, gleitend","alltagsname":"Bein zur Seite schieben","region":"huefte","ziel":"mobilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":[],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"je_seite":true,"taeglich":2},"anleitung":["Legen Sie sich auf den Rücken, die Beine liegen ausgestreckt nebeneinander.","Ziehen Sie die Fußspitzen zu sich, die Kniescheiben zeigen zur Decke.","Schieben Sie ein Bein auf der Unterlage langsam zur Seite und wieder zurück zur Mitte.","Wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Bein dreht nach außen, die Fußspitze kippt zur Seite.","Das Becken rutscht mit zur Seite.","Das Bein wird über die Mitte hinaus zum anderen Bein geführt."],"hinweise_praxis":"Nach Hüftendoprothese: Bewegungsgrenzen nach OP-Bericht und ärztlicher Vorgabe. Beim hinteren Zugang gelten häufig für einige Wochen Grenzen bei Beugung über 90°, Adduktion über die Mittellinie und Innenrotation."},
{"schluessel":"BT-07","version":"1.0.0","name":"Kniestreckung über Rolle (Short Arc Quad)","alltagsname":"Unterschenkel über Rolle strecken","region":"knie","ziel":"kraft","ausgangsstellung":"rueckenlage","hilfsmittel":["kissen"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"halten_s":3,"je_seite":true,"taeglich":2},"anleitung":["Legen Sie sich auf den Rücken und legen Sie ein fest gerolltes Kissen oder eine Decke unter ein Knie.","Heben Sie den Unterschenkel an, bis das Knie gestreckt ist; die Kniekehle bleibt auf der Rolle.","Ziehen Sie die Fußspitze zu sich und halten Sie das Bein 3 Sekunden.","Senken Sie den Fuß langsam ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Die Kniekehle hebt von der Rolle ab.","Der Unterschenkel fällt schnell zurück, statt langsam abgesenkt zu werden."],"hinweise_praxis":"Nach Knieendoprothese keine Dauerlagerung mit Kissen unter dem Knie: Die Rolle nur für die Übung verwenden, sonst droht ein Streckdefizit."},
{"schluessel":"BT-08","version":"1.0.0","name":"Gestrecktes Beinheben (SLR)","alltagsname":"Gestrecktes Bein anheben","region":"knie","ziel":"kraft","ausgangsstellung":"rueckenlage","hilfsmittel":[],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":[8,10],"je_seite":true,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken, stellen Sie ein Bein an und lassen Sie das andere lang liegen.","Ziehen Sie beim langen Bein die Fußspitze zu sich und spannen Sie den Oberschenkel an.","Heben Sie das gestreckte Bein langsam an, bis es etwa so hoch ist wie das andere Knie.","Senken Sie es langsam wieder ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Knie des gehobenen Beins beugt sich.","Das Bein wird mit Schwung gehoben.","Der Rücken drückt sich ins Hohlkreuz."],"hinweise_praxis":"Beugt das Knie beim Heben ab, ist die Übung noch zu schwer; dann zuerst die Kniestreckung über Rolle üben."},
{"schluessel":"BT-09","version":"1.0.0","name":"Drehen auf die Seite, en bloc","alltagsname":"Im Bett auf die Seite drehen","region":"rumpf","ziel":"koordination","ausgangsstellung":"rueckenlage","hilfsmittel":["bett"],"niveau":1,"dosierung":{"wiederholungen":5,"je_seite":true,"taeglich":1},"anleitung":["Legen Sie sich in die Mitte des Bettes auf den Rücken und stellen Sie beide Beine an.","Legen Sie den Arm, der oben bleiben soll, quer über die Brust und blicken Sie zu der Seite, auf die Sie sich drehen.","Drehen Sie Schultern, Becken und Knie gleichzeitig wie ein Brett auf die Seite.","Drehen Sie sich auf demselben Weg zurück und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberkörper dreht vor dem Becken, die Wirbelsäule verdreht sich.","Die Person zieht sich mit einem Ruck an der Bettkante herum."],"hinweise_praxis":"Zuerst gemeinsam im Hausbesuch üben; auf genug Platz zur Bettkante achten, damit beim Drehen niemand herausfällt."},
{"schluessel":"BT-10","version":"1.0.0","name":"Aufsetzen über die Seite an die Bettkante","alltagsname":"Über die Seite aufsetzen","region":"rumpf","ziel":"koordination","ausgangsstellung":"seitlage","hilfsmittel":["bett"],"niveau":1,"dosierung":{"wiederholungen":5,"taeglich":1},"anleitung":["Drehen Sie sich zuerst auf die Seite, mit dem Gesicht zur Bettkante.","Schieben Sie beide Unterschenkel über die Bettkante, sodass sie nach unten hängen.","Drücken Sie sich gleichzeitig mit dem unteren Ellbogen und der oberen Hand hoch, bis Sie sitzen.","Bleiben Sie einen Moment sitzen; wird Ihnen schwindelig, legen Sie sich auf demselben Weg wieder hin."],"fehler":["Die Person zieht sich aus der Rückenlage gerade nach vorn hoch.","Die Beine kommen erst nach dem Oberkörper über die Kante."],"hinweise_praxis":"Kreislauf beachten: Nach längerer Bettruhe vor dem Aufstehen eine Weile sitzen lassen. Zuerst gemeinsam im Hausbesuch üben."},
{"schluessel":"HW-01","version":"1.0.0","name":"Kraniozervikale Flexion (Kinn-Nicken)","alltagsname":"Kinn sanft nicken","region":"hws","ziel":"stabilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":["handtuch"],"niveau":1,"dosierung":{"wiederholungen":10,"halten_s":10,"taeglich":2},"anleitung":["Legen Sie sich auf den Rücken, stellen Sie die Beine an und legen Sie ein flach gefaltetes Handtuch unter den Kopf.","Nicken Sie ganz sanft mit dem Kinn Richtung Brust, als wollten Sie leise „ja“ sagen.","Der Hinterkopf bleibt dabei auf dem Handtuch liegen, der Nacken wird etwas länger.","Halten Sie die Stellung so lange wie im Plan angegeben, atmen Sie ruhig weiter und lassen Sie dann locker."],"fehler":["Der Kopf hebt vom Handtuch ab, statt nur zu nicken.","Die Halsmuskeln vorn spannen sich sichtbar an.","Das Nicken ist zu kräftig; gemeint ist eine kleine, sanfte Bewegung."]},
{"schluessel":"HW-02","version":"1.0.0","name":"HWS-Retraktion im Sitz","alltagsname":"Kinn nach hinten schieben","region":"hws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":10,"taeglich":3},"anleitung":["Setzen Sie sich aufrecht hin, die Schultern sind locker und der Blick geht geradeaus.","Schieben Sie den Kopf langsam waagerecht nach hinten, sodass ein kleines Doppelkinn entsteht.","Der Blick bleibt dabei geradeaus, der Kopf neigt sich weder nach oben noch nach unten.","Halten Sie kurz und lassen Sie den Kopf wieder locker nach vorn gleiten."],"fehler":["Der Kopf neigt sich nach hinten, der Blick geht zur Decke.","Das Kinn wird zur Brust gezogen, statt den Kopf nach hinten zu schieben.","Die Schultern ziehen mit nach oben."]},
{"schluessel":"HW-03","version":"1.0.0","name":"HWS-Rotation, aktiv","alltagsname":"Kopf zur Seite drehen","region":"hws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":10,"je_seite":true,"taeglich":2},"anleitung":["Setzen Sie sich aufrecht hin, die Schultern sind locker.","Drehen Sie den Kopf langsam zu einer Seite, als wollten Sie über die Schulter schauen.","Gehen Sie nur so weit, wie es angenehm ist, und drehen Sie dann ruhig zurück zur Mitte.","Drehen Sie abwechselnd zu beiden Seiten."],"fehler":["Der Oberkörper dreht mit.","Der Kopf neigt sich beim Drehen zur Seite oder nach vorn.","Die Bewegung geht mit Schwung ans Ende."]},
{"schluessel":"HW-04","version":"1.0.0","name":"HWS-Lateralflexion, aktiv","alltagsname":"Ohr Richtung Schulter neigen","region":"hws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":10,"je_seite":true,"taeglich":2},"anleitung":["Setzen Sie sich aufrecht hin, die Arme hängen locker.","Neigen Sie den Kopf langsam zur Seite, das Ohr wandert Richtung Schulter.","Die Nase zeigt dabei weiter nach vorn, und die Schulter bleibt unten.","Kommen Sie ruhig zurück zur Mitte und neigen Sie abwechselnd zu beiden Seiten."],"fehler":["Die Schulter wird zum Ohr hochgezogen.","Der Kopf dreht sich beim Neigen mit."]},
{"schluessel":"HW-05","version":"1.0.0","name":"Dehnung M. trapezius pars descendens","alltagsname":"Nacken seitlich dehnen","region":"hws","ziel":"dehnung","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl und halten Sie sich mit der rechten Hand seitlich an der Sitzfläche fest.","Neigen Sie den Kopf langsam zur linken Schulter, die Nase zeigt weiter nach vorn.","Legen Sie die linke Hand auf den Kopf und verstärken Sie die Neigung nur ganz sanft, bis Sie rechts im Nacken eine Dehnung spüren.","Halten Sie die Dehnung ruhig, atmen Sie weiter und wechseln Sie danach die Seite."],"fehler":["Die Hand zieht kräftig am Kopf.","Die Schulter der gedehnten Seite zieht nach oben.","Der Kopf dreht sich, statt sich zu neigen."]},
{"schluessel":"HW-06","version":"1.0.0","name":"Dehnung des Schulterblatthebers","alltagsname":"Nacken schräg nach vorn dehnen","region":"hws","ziel":"dehnung","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl und halten Sie sich mit der rechten Hand seitlich an der Sitzfläche fest.","Drehen Sie den Kopf etwa halb nach links und neigen Sie ihn dann nach vorn, als wollten Sie in die linke Achsel schauen.","Legen Sie die linke Hand auf den Hinterkopf und lassen Sie das Gewicht des Arms die Dehnung rechts hinten im Nacken sanft verstärken.","Halten Sie die Dehnung ruhig, atmen Sie weiter und wechseln Sie danach die Seite."],"fehler":["Die Hand zieht den Kopf kräftig nach unten.","Die Schulter der gedehnten Seite zieht nach oben.","Der Rücken wird rund, statt nur den Kopf zu neigen."]},
{"schluessel":"HW-07","version":"1.0.0","name":"HWS-Isometrie gegen Handwiderstand","alltagsname":"Kopf gegen die Hand drücken","region":"hws","ziel":"stabilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":2,"dosierung":{"wiederholungen":5,"halten_s":5,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht hin und legen Sie eine Hand seitlich an den Kopf, über dem Ohr.","Drücken Sie den Kopf sanft gegen die Hand und halten Sie mit der Hand dagegen, sodass sich der Kopf nicht bewegt.","Halten Sie den Druck, atmen Sie dabei weiter und lassen Sie langsam los.","Üben Sie jede Richtung so oft wie im Plan: zu beiden Seiten, mit der Hand an der Stirn und mit beiden Händen am Hinterkopf."],"fehler":["Es wird mit voller Kraft gedrückt; gemeint ist ein leichter Druck.","Der Kopf weicht aus und bewegt sich.","Die Luft wird angehalten."],"hinweise_praxis":"Die Dosierung gilt je Richtung: rechts, links, Stirn und Hinterkopf. Das Bild zeigt nur die Hand an der Seite."},
{"schluessel":"HW-08","version":"1.0.0","name":"Hinterkopf in die Unterlage drücken","alltagsname":"Hinterkopf sanft ins Kissen drücken","region":"hws","ziel":"kraft","ausgangsstellung":"rueckenlage","hilfsmittel":["kissen"],"niveau":1,"dosierung":{"wiederholungen":10,"halten_s":5,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken, der Kopf liegt auf einem flachen Kissen, die Beine sind angestellt.","Ziehen Sie das Kinn leicht ein und drücken Sie den Hinterkopf sanft in das Kissen.","Halten Sie den Druck, atmen Sie ruhig weiter und lassen Sie dann locker."],"fehler":["Das Kinn hebt sich, der Kopf wird nach hinten überstreckt.","Es wird so fest gedrückt, dass sich die Schultern anspannen oder abheben."]},
{"schluessel":"HW-09","version":"1.0.0","name":"Kopfabheben mit Kinn-Nicken (Ausdauer der Nackenbeuger)","alltagsname":"Kopf mit eingezogenem Kinn anheben","region":"hws","ziel":"kraft","ausgangsstellung":"rueckenlage","hilfsmittel":[],"niveau":3,"dosierung":{"wiederholungen":5,"halten_s":10,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken und stellen Sie die Beine an.","Nicken Sie das Kinn sanft ein und halten Sie es so.","Heben Sie den Kopf nur wenige Zentimeter von der Unterlage ab, das Kinn bleibt eingezogen.","Halten Sie den Kopf ruhig in der Luft und legen Sie ihn dann langsam wieder ab."],"fehler":["Das Kinn schiebt sich nach vorn zur Decke.","Der Kopf wird zu hoch gehoben.","Der Kopf zittert, weil die Haltezeit zu lang ist."],"hinweise_praxis":"Die Haltezeit endet, sobald das Kinn nach vorn schiebt oder der Kopf zittert; dann im Plan kürzer dosieren."},
{"schluessel":"HW-10","version":"1.0.0","name":"Selbstmobilisation obere HWS mit Handtuch (Rotation)","alltagsname":"Kopf mit dem Handtuch drehen","region":"hws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["handtuch"],"niveau":3,"dosierung":{"wiederholungen":6,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht hin und legen Sie ein Handtuch quer um den oberen Nacken, direkt unter dem Hinterkopf.","Halten Sie ein Ende unten vor der Brust fest und führen Sie das andere Ende so nach vorn, wie es Ihnen in der Praxis gezeigt wurde.","Drehen Sie den Kopf langsam zur Seite, das Handtuch begleitet und unterstützt die Drehung.","Halten Sie am Ende der Drehung kurz und drehen Sie ruhig zurück zur Mitte.","Hören Sie sofort auf, wenn Ihnen schwindelig oder übel wird."],"fehler":["Das Handtuch liegt zu tief am Nacken.","Es wird mit Schwung oder kräftigem Zug gedreht.","Der Oberkörper dreht mit."],"hinweise_praxis":"Nur nach Befund der oberen Halswirbelsäule und nach gemeinsamem Einüben; Griff und Zugrichtung vor Ort zeigen. Bei Schwindel, Sehstörungen, Übelkeit oder Kribbeln abbrechen."},
{"schluessel":"HW-11","version":"1.0.0","name":"Nackenstreckung im Vierfüßlerstand","alltagsname":"Im Vierfüßler Kopf heben und senken","region":"hws","ziel":"stabilitaet","ausgangsstellung":"vierfuessler","hilfsmittel":["matte"],"niveau":3,"dosierung":{"saetze":2,"wiederholungen":10},"anleitung":["Gehen Sie auf einer Matte in den Vierfüßlerstand: Hände unter den Schultern, Knie unter den Hüften.","Halten Sie den Rücken gerade und lassen Sie den Kopf mit leicht eingezogenem Kinn nach unten sinken.","Heben Sie den Kopf langsam an, bis er wieder in einer Linie mit dem Rücken ist.","Schauen Sie dabei weiter zum Boden und heben Sie den Kopf nicht über die Linie des Rückens."],"fehler":["Der Kopf wird über die Linie des Rückens hinaus in den Nacken gelegt.","Der Rücken hängt durch oder wird rund.","Die Schultern sinken zwischen die Arme."],"hinweise_praxis":"Der Vierfüßlerstand ist für viele Ältere wegen Knien oder Handgelenken nicht möglich; dann eine Übung im Sitz aus derselben Gruppe wählen."},
{"schluessel":"BW-01","version":"1.0.0","name":"Aufrichtung im Sitz","alltagsname":"Sich groß machen","region":"bws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"wiederholungen":10,"halten_s":5,"taeglich":3},"anleitung":["Setzen Sie sich auf einen Stuhl, ohne sich anzulehnen, die Füße stehen flach auf dem Boden.","Lassen Sie den Rücken zuerst locker rund werden.","Richten Sie sich dann langsam auf, als zöge ein Faden am Scheitel Sie nach oben.","Halten Sie die aufrechte Haltung, atmen Sie ruhig weiter und lassen Sie wieder locker."],"fehler":["Das Kinn wird nach vorn oben geschoben, statt den Hinterkopf lang zu machen.","Es entsteht ein starkes Hohlkreuz.","Die Schultern ziehen zu den Ohren."],"hinweise_praxis":"Gedacht als kurze Haltungspause mehrmals am Tag; 3-mal täglich ist nur der Startwert."},
{"schluessel":"BW-02","version":"1.0.0","name":"Skapula-Retraktion im Sitz","alltagsname":"Schulterblätter nach hinten-unten ziehen","region":"bws","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"halten_s":3,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Hände liegen locker auf den Oberschenkeln.","Ziehen Sie beide Schulterblätter sanft nach hinten und unten, als wollten Sie sie in die hinteren Hosentaschen stecken.","Halten Sie die Spannung und atmen Sie dabei ruhig weiter.","Lassen Sie die Schultern langsam wieder locker."],"fehler":["Die Schultern werden zu den Ohren hochgezogen.","Der Rücken geht ins Hohlkreuz, statt nur die Schulterblätter zu bewegen.","Das Kinn schiebt sich nach vorn."]},
{"schluessel":"BW-03","version":"1.0.0","name":"BWS-Extension über die Stuhllehne","alltagsname":"Über die Lehne nach hinten strecken","region":"bws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"wiederholungen":10,"taeglich":1},"anleitung":["Setzen Sie sich auf einen Stuhl mit fester Lehne, der Rücken lehnt an.","Verschränken Sie die Hände hinter dem Kopf, die Ellbogen zeigen nach vorn.","Lehnen Sie den oberen Rücken langsam über die Oberkante der Lehne nach hinten und schauen Sie dabei leicht nach oben.","Kommen Sie ruhig zurück in den aufrechten Sitz."],"fehler":["Die Bewegung kommt aus dem unteren Rücken, das Gesäß rutscht nach vorn.","Der Kopf wird mit den Händen in den Nacken gezogen.","Es wird mit Schwung nach hinten gelehnt."],"hinweise_praxis":"Nur mit standfestem Stuhl, der nicht nach hinten kippen kann; die Lehne sollte etwa bis zur Mitte des Rückens reichen."},
{"schluessel":"BW-04","version":"1.0.0","name":"BWS-Rotation im Sitz","alltagsname":"Oberkörper drehen","region":"bws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Füße stehen fest auf dem Boden.","Kreuzen Sie die Arme vor der Brust, die Hände liegen auf den Schultern.","Drehen Sie den Oberkörper langsam zu einer Seite, so weit es angenehm geht; die Knie zeigen weiter nach vorn.","Drehen Sie ruhig zurück zur Mitte und wechseln Sie die Seite."],"fehler":["Das Becken und die Knie drehen mit.","Der Oberkörper neigt sich beim Drehen zur Seite.","Die Drehung wird mit Schwung ans Ende geführt."]},
{"schluessel":"BW-05","version":"1.0.0","name":"Rumpfseitneige im Sitz","alltagsname":"Zur Seite neigen","region":"bws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Füße stehen hüftbreit auf dem Boden.","Stützen Sie eine Hand in die Hüfte und lassen Sie den anderen Arm locker hängen.","Neigen Sie den Oberkörper langsam zur Seite des hängenden Arms, die Hand sinkt Richtung Boden.","Richten Sie sich ruhig wieder auf; beide Gesäßhälften bleiben dabei auf dem Stuhl.","Wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Eine Gesäßhälfte hebt vom Stuhl ab.","Der Oberkörper kippt nach vorn, statt sich zur Seite zu neigen."],"hinweise_praxis":"Bei Unsicherheit im Sitz einen Stuhl mit Armlehnen wählen oder seitlich sichern."},
{"schluessel":"BW-06","version":"1.0.0","name":"Offenes Buch (Rotation in Seitlage)","alltagsname":"Arm in Seitlage aufklappen","region":"bws","ziel":"mobilitaet","ausgangsstellung":"seitlage","hilfsmittel":["kissen"],"niveau":2,"dosierung":{"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Legen Sie sich auf die Seite, der Kopf liegt auf einem Kissen, Hüften und Knie sind etwa rechtwinklig gebeugt.","Strecken Sie beide Arme auf Schulterhöhe nach vorn, die Handflächen liegen aufeinander.","Öffnen Sie den oberen Arm langsam in einem Bogen nach hinten und schauen Sie der Hand nach, die Knie bleiben aufeinander.","Führen Sie den Arm ruhig wieder zurück und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das obere Knie rutscht vom unteren weg, das Becken dreht mit.","Der Arm wird mit Schwung nach hinten geworfen.","Der Kopf bleibt stehen, statt der Hand zu folgen."],"hinweise_praxis":"Den Arm nur so weit öffnen, wie es ohne Schmerz in der Schulter geht; er muss den Boden nicht erreichen."},
{"schluessel":"BW-07","version":"1.0.0","name":"Katzenbuckel und Pferderücken","alltagsname":"Rücken rund und hohl machen","region":"bws","ziel":"mobilitaet","ausgangsstellung":"vierfuessler","hilfsmittel":["matte"],"niveau":2,"dosierung":{"wiederholungen":10,"taeglich":1},"anleitung":["Gehen Sie auf einer Matte in den Vierfüßlerstand: Hände unter den Schultern, Knie unter den Hüften.","Machen Sie den Rücken langsam rund wie eine Katze und lassen Sie dabei den Kopf sinken.","Lassen Sie den Rücken danach langsam etwas durchhängen und heben Sie den Blick leicht an.","Wechseln Sie ruhig und fließend zwischen beiden Stellungen und atmen Sie dabei weiter."],"fehler":["Der Kopf wird im Hohlkreuz weit in den Nacken gelegt.","Die Bewegung kommt nur aus dem unteren Rücken.","Die Arme beugen sich, statt gestreckt zu bleiben."],"hinweise_praxis":"Der Vierfüßlerstand ist für viele Ältere wegen Knien oder Handgelenken nicht möglich; dann eine Übung im Sitz aus derselben Gruppe wählen."},
{"schluessel":"BW-08","version":"1.0.0","name":"Rudern mit Theraband","alltagsname":"Band zum Körper ziehen","region":"bws","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["theraband","stuhl","tuerrahmen"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12},"anleitung":["Befestigen Sie das Band in Brusthöhe an einem festen Halt vor Ihnen, etwa an einer Türklinke.","Setzen Sie sich aufrecht auf einen Stuhl und fassen Sie die Enden mit gestreckten Armen.","Ziehen Sie die Ellbogen dicht am Körper nach hinten und die Schulterblätter zueinander.","Lassen Sie die Arme langsam und kontrolliert wieder nach vorn."],"fehler":["Der Oberkörper lehnt sich nach hinten, statt nur die Arme zu bewegen.","Die Schultern ziehen zu den Ohren.","Das Band schnellt zurück, statt langsam nachgelassen zu werden."],"hinweise_praxis":"Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“."},
{"schluessel":"BW-09","version":"1.0.0","name":"Band auseinanderziehen (Pull-Apart)","alltagsname":"Band vor der Brust auseinanderziehen","region":"bws","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["theraband"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12},"anleitung":["Stellen Sie sich aufrecht hin und fassen Sie das Band schulterbreit mit beiden Händen.","Heben Sie die gestreckten Arme vor dem Körper auf Brusthöhe.","Ziehen Sie das Band langsam auseinander, bis die Arme zur Seite zeigen, und führen Sie die Schulterblätter dabei zueinander.","Lassen Sie die Arme langsam wieder zusammenkommen."],"fehler":["Die Schultern ziehen zu den Ohren.","Der Rücken geht ins Hohlkreuz.","Die Ellbogen beugen sich stark."],"hinweise_praxis":"Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“."},
{"schluessel":"BW-10","version":"1.0.0","name":"Wandengel (Arme an der Wand gleiten)","alltagsname":"Arme an der Wand hochschieben","region":"bws","ziel":"mobilitaet","ausgangsstellung":"stand","hilfsmittel":["wand"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich mit dem Rücken an eine Wand, die Füße stehen eine Fußlänge davor.","Legen Sie Hinterkopf, Rücken und Gesäß an die Wand und heben Sie die Arme seitlich, die Ellbogen sind rechtwinklig gebeugt.","Schieben Sie die Arme langsam an der Wand nach oben, so weit es geht, ohne dass der Rücken sich löst.","Gleiten Sie ruhig zurück in die Ausgangsstellung."],"fehler":["Der untere Rücken löst sich von der Wand, ein Hohlkreuz entsteht.","Die Schultern ziehen zu den Ohren.","Die Arme verlieren den Kontakt zur Wand."],"hinweise_praxis":"Erreichen die Unterarme die Wand nicht, nur so weit bewegen, wie Rücken und Kopf an der Wand bleiben."},
{"schluessel":"BW-11","version":"1.0.0","name":"Brustmuskeldehnung im Türrahmen","alltagsname":"Brust im Türrahmen dehnen","region":"bws","ziel":"dehnung","ausgangsstellung":"stand","hilfsmittel":["tuerrahmen"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"taeglich":1},"anleitung":["Stellen Sie sich in eine offene Tür.","Legen Sie beide Unterarme an den Türrahmen, die Ellbogen sind etwa auf Schulterhöhe.","Machen Sie einen kleinen Schritt nach vorn, bis Sie vorn an der Brust eine Dehnung spüren.","Halten Sie die Dehnung ruhig, atmen Sie weiter und treten Sie dann wieder zurück."],"fehler":["Der Rücken geht ins Hohlkreuz, statt den Oberkörper aufrecht zu halten.","Die Schultern ziehen nach oben.","Der Schritt ist so groß, dass es in der Schulter zieht oder kribbelt."],"hinweise_praxis":"Kribbeln oder Taubheit im Arm sind kein Dehngefühl: dann die Ellbogen tiefer legen oder den Schritt verkleinern."},
{"schluessel":"BW-12","version":"1.0.0","name":"Armheben in Bauchlage (Y und T)","alltagsname":"In Bauchlage Arme anheben","region":"bws","ziel":"kraft","ausgangsstellung":"bauchlage","hilfsmittel":["kissen","matte"],"niveau":3,"dosierung":{"saetze":2,"wiederholungen":[8,10]},"anleitung":["Legen Sie sich auf den Bauch, ein flaches Kissen liegt unter dem Bauch, die Stirn ruht auf der Unterlage.","Strecken Sie die Arme schräg nach vorn aus wie ein Y, die Daumen zeigen nach oben.","Heben Sie beide Arme ein kleines Stück von der Unterlage ab, halten Sie kurz und legen Sie sie langsam ab.","Üben Sie danach genauso mit seitlich ausgestreckten Armen wie ein T."],"fehler":["Der Kopf wird angehoben und in den Nacken gelegt.","Die Schultern ziehen zu den Ohren.","Der untere Rücken geht ins Hohlkreuz."],"hinweise_praxis":"Bauchlage ist für viele Hochbetagte nicht möglich (Atmung, Herz, Endoprothese); dann im Sitz üben, etwa „Rudern mit Theraband“."},
{"schluessel":"LW-01","version":"1.0.0","name":"Beckenkippen in Rückenlage","alltagsname":"Becken vor und zurück kippen","region":"lws","ziel":"mobilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken und stellen Sie beide Beine an, die Füße stehen hüftbreit.","Kippen Sie das Becken nach hinten, sodass der untere Rücken sanft in die Unterlage drückt.","Kippen Sie das Becken danach nach vorn, bis unter dem unteren Rücken ein kleines Hohlkreuz entsteht.","Bewegen Sie sich langsam und im Rhythmus Ihres Atems."],"fehler":["Das Gesäß hebt von der Unterlage ab.","Die Bewegung kommt aus den Beinen statt aus dem Becken.","Die Luft wird angehalten."]},
{"schluessel":"LW-02","version":"1.0.0","name":"Beckenkippen im Sitz","alltagsname":"Im Sitz rund und gerade werden","region":"lws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Setzen Sie sich vorn auf die Stuhlkante, die Füße stehen hüftbreit auf dem Boden.","Kippen Sie das Becken nach hinten und lassen Sie den Rücken dabei rund werden.","Kippen Sie das Becken danach nach vorn, bis der Rücken aufgerichtet und gerade ist.","Bewegen Sie sich langsam hin und her, der Kopf bleibt dabei über dem Becken."],"fehler":["Nur Kopf und Schultern bewegen sich, das Becken bleibt stehen.","Beim Aufrichten entsteht ein starkes Hohlkreuz."]},
{"schluessel":"LW-03","version":"1.0.0","name":"Knie zur Brust, einbeinig","alltagsname":"Ein Knie zur Brust ziehen","region":"lws","ziel":"dehnung","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":1,"dosierung":{"saetze":5,"dauer_s":20,"je_seite":true,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken und stellen Sie beide Beine an.","Fassen Sie ein Knie mit beiden Händen und ziehen Sie es sanft Richtung Brust.","Halten Sie die Dehnung ruhig, das andere Bein bleibt angestellt.","Lassen Sie das Bein langsam zurück und wechseln Sie die Seite."],"fehler":["Der Kopf hebt von der Unterlage ab.","Es wird ruckartig gezogen."],"hinweise_praxis":"Nach Hüftendoprothese gelten die Bewegungsgrenzen des Zugangs: Beim hinteren Zugang ist eine Beugung über 90° häufig für einige Wochen nicht erlaubt, das operierte Bein dann nicht zur Brust ziehen."},
{"schluessel":"LW-04","version":"1.0.0","name":"Beide Knie zur Brust","alltagsname":"Beide Knie zur Brust ziehen","region":"lws","ziel":"dehnung","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":2,"dosierung":{"saetze":5,"dauer_s":20,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken und stellen Sie beide Beine an.","Ziehen Sie erst ein Knie, dann das andere Richtung Brust und fassen Sie beide mit den Händen.","Ziehen Sie die Knie sanft heran, bis Sie im unteren Rücken eine Dehnung spüren, und halten Sie diese ruhig.","Stellen Sie die Füße nacheinander wieder ab."],"fehler":["Beide Beine werden mit Schwung gleichzeitig angehoben.","Der Kopf hebt von der Unterlage ab.","Die Luft wird angehalten."],"hinweise_praxis":"Bei Osteoporose keine belastete, endgradige Beugung der Wirbelsäule. Nach Hüftendoprothese mit hinterem Zugang ist eine Beugung über 90° häufig für einige Wochen nicht erlaubt."},
{"schluessel":"LW-05","version":"1.0.0","name":"Knie seitlich ablegen (Rotation in Rückenlage)","alltagsname":"Knie zur Seite kippen","region":"lws","ziel":"mobilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken, stellen Sie beide Beine an und legen Sie die Arme seitlich ab.","Lassen Sie beide Knie zusammen langsam zu einer Seite sinken, so weit es angenehm ist.","Die Schultern bleiben dabei auf der Unterlage liegen.","Holen Sie die Knie zurück zur Mitte und wechseln Sie die Seite."],"fehler":["Die Knie fallen mit Schwung zur Seite.","Die gegenüberliegende Schulter hebt ab."],"hinweise_praxis":"Nach Hüftendoprothese mit hinterem Zugang: Sinken die Knie zur Gegenseite, gerät das operierte Bein in Adduktion und Innenrotation; das Ausmaß dann nach ärztlicher Vorgabe begrenzen."},
{"schluessel":"LW-06","version":"1.0.0","name":"Rumpfbeuge im Sitz (Abrollen)","alltagsname":"Im Sitz nach vorn abrollen","region":"lws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Füße stehen hüftbreit auf dem Boden.","Senken Sie das Kinn zur Brust und rollen Sie den Oberkörper langsam nach vorn ab.","Lassen Sie die Hände dabei an den Beinen entlang nach unten gleiten, so weit es angenehm ist.","Rollen Sie sich langsam wieder auf, der Kopf kommt zuletzt."],"fehler":["Der Oberkörper kippt mit Schwung nach vorn.","Beim Aufrichten wird zuerst der Kopf gehoben."],"hinweise_praxis":"Bei Osteoporose keine belastete, endgradige Beugung der Wirbelsäule. Nach Hüftendoprothese mit hinterem Zugang nur so weit vorneigen, dass die Hüfte nicht über 90° gebeugt wird. Bei Neigung zu Schwindel langsam aufrichten und kurz sitzen bleiben."},
{"schluessel":"LW-07","version":"1.0.0","name":"Extension in Bauchlage auf den Unterarmen","alltagsname":"Auf die Unterarme stützen","region":"lws","ziel":"mobilitaet","ausgangsstellung":"bauchlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":2,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":5,"taeglich":1},"anleitung":["Legen Sie sich auf den Bauch, die Unterarme liegen neben dem Kopf.","Stützen Sie sich langsam auf die Unterarme, die Ellbogen stehen unter den Schultern.","Lassen Sie Becken und Bauch locker auf der Unterlage liegen und halten Sie 5 Sekunden.","Legen Sie sich langsam wieder ab."],"fehler":["Das Becken hebt von der Unterlage ab.","Die Schultern ziehen zu den Ohren.","Der Kopf wird weit in den Nacken gelegt."],"hinweise_praxis":"Bauchlage ist für viele Hochbetagte nicht möglich (Atmung, Herz, Endoprothese); dann das Beckenkippen im Sitz wählen. Strahlen Beschwerden während der Übung weiter ins Bein aus, die Übung beenden."},
{"schluessel":"LW-08","version":"1.0.0","name":"Päckchensitz (Kindhaltung)","alltagsname":"Im Fersensitz nach vorn legen","region":"lws","ziel":"dehnung","ausgangsstellung":"vierfuessler","hilfsmittel":["matte"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"taeglich":1},"anleitung":["Gehen Sie auf einer Matte in den Vierfüßlerstand, die Hände stehen unter den Schultern.","Schieben Sie das Gesäß langsam Richtung Fersen, die Hände bleiben vorn liegen.","Legen Sie die Stirn ab, wenn es geht, und atmen Sie ruhig in den Rücken.","Kommen Sie langsam zurück in den Vierfüßlerstand."],"fehler":["Die Hände rutschen mit nach hinten.","Es wird mit Schwung in die Dehnung gegangen."],"hinweise_praxis":"Bei Osteoporose keine belastete, endgradige Beugung der Wirbelsäule. Verlangt starke Knie- und Hüftbeugung und ist nach Knie- oder Hüftendoprothese meist nicht geeignet; ein Kissen zwischen Gesäß und Fersen verringert die Beugung."},
{"schluessel":"LW-09","version":"1.0.0","name":"Aktivierung M. transversus abdominis","alltagsname":"Bauch sanft nach innen ziehen","region":"rumpf","ziel":"stabilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":10,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken, stellen Sie die Beine an und legen Sie die Hände auf den Unterbauch.","Atmen Sie ruhig aus und ziehen Sie den Bauchnabel dabei sanft nach innen, ohne das Becken zu bewegen.","Halten Sie die leichte Spannung 10 Sekunden und atmen Sie dabei ruhig weiter.","Lassen Sie die Spannung langsam wieder los."],"fehler":["Die Luft wird angehalten.","Das Becken kippt mit oder das Gesäß wird angespannt.","Es wird zu kräftig angespannt."]},
{"schluessel":"LW-10","version":"1.0.0","name":"Fersentippen in Rückenlage","alltagsname":"Beine im Wechsel abheben","region":"rumpf","ziel":"stabilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"je_seite":true},"anleitung":["Legen Sie sich auf den Rücken und stellen Sie beide Beine an.","Spannen Sie den Bauch leicht an, sodass das Becken ruhig liegt.","Heben Sie einen Fuß langsam ab, bis das Knie über der Hüfte steht, und setzen Sie die Ferse wieder ab.","Wechseln Sie das Bein und atmen Sie dabei ruhig weiter."],"fehler":["Das Becken kippt zur Seite oder ins Hohlkreuz.","Das Bein fällt schnell zurück.","Die Luft wird angehalten."],"hinweise_praxis":"Nach Hüftendoprothese mit hinterem Zugang das Knie nur bis knapp unter 90° Beugung heben, solange die Grenze gilt."},
{"schluessel":"LW-11","version":"1.0.0","name":"Dead Bug (Arm und Bein diagonal)","alltagsname":"Arm und Bein im Wechsel strecken","region":"rumpf","ziel":"stabilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":8,"je_seite":true},"anleitung":["Legen Sie sich auf den Rücken und heben Sie beide Beine an, bis die Knie rechtwinklig über der Hüfte stehen.","Strecken Sie beide Arme zur Decke.","Strecken Sie langsam einen Arm nach hinten und das gegenüberliegende Bein nach vorn, der untere Rücken bleibt auf der Unterlage.","Holen Sie Arm und Bein zurück und wechseln Sie die Seite."],"fehler":["Der untere Rücken hebt von der Unterlage ab.","Arm und Bein werden zu schnell bewegt.","Die Luft wird angehalten."],"hinweise_praxis":"Gelingt es nicht, den Rücken ruhig zu halten, zuerst nur ein Bein bewegen und die Füße zwischendurch abstellen. Nach Hüftendoprothese mit hinterem Zugang ist die Ausgangsstellung mit 90° Hüftbeugung grenzwertig."},
{"schluessel":"LW-12","version":"1.0.0","name":"Brücke (Becken heben)","alltagsname":"Becken anheben","region":"lws","ziel":"kraft","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Legen Sie sich auf den Rücken, stellen Sie beide Beine hüftbreit an, die Arme liegen neben dem Körper.","Spannen Sie das Gesäß an und heben Sie das Becken langsam, bis Oberkörper und Oberschenkel eine Linie bilden.","Halten Sie kurz und legen Sie den Rücken langsam wieder ab."],"fehler":["Das Becken wird zu hoch gedrückt, es entsteht ein Hohlkreuz.","Die Knie fallen nach innen oder außen.","Das Becken kippt zu einer Seite."]},
{"schluessel":"LW-13","version":"1.0.0","name":"Einbeinige Brücke","alltagsname":"Becken auf einem Bein heben","region":"lws","ziel":"kraft","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":8,"je_seite":true},"anleitung":["Legen Sie sich auf den Rücken und stellen Sie beide Beine an.","Strecken Sie ein Bein aus, beide Oberschenkel bleiben auf gleicher Höhe.","Heben Sie das Becken mit der Kraft des aufgestellten Beins, bis Oberkörper und Oberschenkel eine Linie bilden.","Senken Sie das Becken langsam ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Becken sinkt auf der Seite des gestreckten Beins ab.","Es entsteht ein Hohlkreuz.","Das gestreckte Bein wird höher gehoben als der andere Oberschenkel."]},
{"schluessel":"LW-14","version":"1.0.0","name":"Vierfüßler, Arm und Bein diagonal","alltagsname":"Im Vierfüßler Arm und Bein strecken","region":"rumpf","ziel":"stabilitaet","ausgangsstellung":"vierfuessler","hilfsmittel":["matte"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":8,"halten_s":5,"je_seite":true},"anleitung":["Gehen Sie auf einer Matte in den Vierfüßlerstand, die Hände unter den Schultern, die Knie unter der Hüfte.","Strecken Sie langsam einen Arm nach vorn und das gegenüberliegende Bein nach hinten aus.","Halten Sie Rücken und Becken dabei ruhig und waagerecht, 5 Sekunden lang.","Setzen Sie Arm und Bein wieder ab und wechseln Sie die Seite."],"fehler":["Das Bein wird zu hoch gehoben, es entsteht ein Hohlkreuz.","Das Becken dreht sich zur Seite auf.","Der Kopf hängt nach unten oder wird in den Nacken gelegt."],"hinweise_praxis":"Belastet Hand- und Kniegelenke; bei Beschwerden dort den Dead Bug in Rückenlage wählen. Zum Einstieg nur den Arm oder nur das Bein bewegen."},
{"schluessel":"LW-15","version":"1.0.0","name":"Unterarmstütz an der Arbeitsplatte","alltagsname":"Schräg an der Arbeitsplatte abstützen","region":"rumpf","ziel":"stabilitaet","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":20},"anleitung":["Legen Sie die Unterarme auf die Arbeitsplatte, die Ellbogen stehen unter den Schultern.","Gehen Sie mit den Füßen so weit zurück, dass der Körper von Kopf bis Ferse eine schräge Linie bildet.","Spannen Sie Bauch und Gesäß leicht an und halten Sie die Stellung, ohne die Luft anzuhalten.","Gehen Sie zum Lösen mit den Füßen wieder näher an die Arbeitsplatte."],"fehler":["Das Becken hängt durch, es entsteht ein Hohlkreuz.","Das Gesäß wird nach oben geschoben.","Die Luft wird angehalten."],"hinweise_praxis":"Pressatmung vermeiden, besonders bei Bluthochdruck. Die Arbeitsplatte muss fest stehen, die Schuhe rutschfest sein. Die Haltezeit von 20 auf 30 Sekunden steigern."},
{"schluessel":"LW-16","version":"1.0.0","name":"Unterarmstütz am Boden (Plank)","alltagsname":"Auf Unterarmen und Knien halten","region":"rumpf","ziel":"stabilitaet","ausgangsstellung":"bauchlage","hilfsmittel":["matte"],"niveau":3,"dosierung":{"saetze":3,"dauer_s":20},"anleitung":["Legen Sie sich auf einer Matte auf den Bauch und stützen Sie sich auf die Unterarme, die Ellbogen unter den Schultern.","Heben Sie das Becken an, bis der Körper von den Knien bis zum Kopf eine gerade Linie bildet.","Halten Sie die Stellung und atmen Sie ruhig weiter.","Legen Sie das Becken langsam wieder ab."],"fehler":["Das Becken hängt durch.","Das Gesäß ragt nach oben.","Die Luft wird angehalten."],"hinweise_praxis":"Bauchlage ist für viele Hochbetagte nicht möglich (Atmung, Herz, Endoprothese); dann den Unterarmstütz an der Arbeitsplatte wählen. Pressatmung vermeiden. Steigerung: auf den Zehen statt auf den Knien."},
{"schluessel":"LW-17","version":"1.0.0","name":"Seitstütz auf den Knien","alltagsname":"Seitlich auf Unterarm und Knie stützen","region":"rumpf","ziel":"stabilitaet","ausgangsstellung":"seitlage","hilfsmittel":["matte"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":15,"je_seite":true},"anleitung":["Legen Sie sich auf einer Matte auf die Seite, beugen Sie die Knie und stützen Sie sich auf den unteren Unterarm.","Der Ellbogen steht unter der Schulter, die obere Hand liegt auf der Hüfte.","Heben Sie das Becken an, bis Oberkörper und Oberschenkel eine Linie bilden, und halten Sie die Stellung.","Legen Sie das Becken langsam ab und wechseln Sie die Seite."],"fehler":["Das Becken sinkt ab oder kippt nach hinten.","Die Schulter zieht zum Ohr.","Die Luft wird angehalten."],"hinweise_praxis":"Belastet die Schulter des Stützarms; bei Beschwerden dort nicht üben. Liegen auf der operierten Seite nach Hüftendoprothese nur nach ärztlicher Vorgabe."},
{"schluessel":"LW-18","version":"1.0.0","name":"Arm und Bein heben in Bauchlage, gegenseitig","alltagsname":"In Bauchlage Arm und Bein anheben","region":"lws","ziel":"kraft","ausgangsstellung":"bauchlage","hilfsmittel":["kissen"],"hilfsmittel_optional":["matte"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":8,"je_seite":true},"anleitung":["Legen Sie sich auf den Bauch, ein flaches Kissen liegt unter dem Bauch, die Arme sind nach vorn ausgestreckt.","Heben Sie einen Arm und das gegenüberliegende Bein gleichzeitig ein kleines Stück an.","Der Blick bleibt zur Unterlage gerichtet, Kopf und Becken bleiben ruhig.","Legen Sie Arm und Bein langsam ab und wechseln Sie die Seite."],"fehler":["Arm und Bein werden zu hoch gehoben, es entsteht ein starkes Hohlkreuz.","Der Kopf wird in den Nacken gelegt.","Das Becken dreht sich mit."],"hinweise_praxis":"Bauchlage ist für viele Hochbetagte nicht möglich (Atmung, Herz, Endoprothese); dann den Vierfüßler, Arm und Bein diagonal oder den Dead Bug wählen. Bei Schulterbeschwerden die Arme neben dem Körper lassen und nur das Bein heben."},
{"schluessel":"LW-19","version":"1.0.0","name":"Hüftbeuge mit Stab (Hip Hinge)","alltagsname":"Mit geradem Rücken vorbeugen","region":"lws","ziel":"koordination","ausgangsstellung":"stand","hilfsmittel":["stab"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Halten Sie einen Stab hinter dem Rücken, sodass er Hinterkopf, Brustkorb und Kreuzbein berührt.","Stellen Sie die Füße hüftbreit und beugen Sie die Knie leicht.","Schieben Sie das Gesäß nach hinten und neigen Sie den Oberkörper nach vorn, ohne dass sich der Stab vom Rücken löst.","Richten Sie sich über die Hüfte wieder auf."],"fehler":["Der Rücken wird rund, der Stab löst sich vom Kreuzbein.","Die Knie beugen sich stark, statt das Gesäß nach hinten zu schieben.","Der Kopf wird in den Nacken gelegt."]},
{"schluessel":"LW-20","version":"1.0.0","name":"Anti-Rotation mit Band (Pallof Press)","alltagsname":"Band vor der Brust wegdrücken","region":"rumpf","ziel":"stabilitaet","ausgangsstellung":"stand","hilfsmittel":["theraband","tuerrahmen"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Befestigen Sie das Band in Brusthöhe an einem festen Gegenstand, etwa am Türrahmen.","Stellen Sie sich seitlich zur Befestigung und halten Sie das Band mit beiden Händen vor der Brust.","Drücken Sie die Hände langsam gerade nach vorn, ohne dass sich der Oberkörper zum Band dreht.","Führen Sie die Hände zurück zur Brust und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberkörper dreht sich zur Befestigung.","Die Schultern ziehen hoch.","Das Becken weicht zur Seite aus."],"hinweise_praxis":"Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“. Mehr Abstand zur Befestigung erhöht den Zug."},
{"schluessel":"SH-01","version":"1.0.0","name":"Pendelübung (Codman)","alltagsname":"Arm locker pendeln lassen","region":"schulter","ziel":"mobilitaet","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":1,"dauer_s":60,"taeglich":3},"anleitung":["Stellen Sie sich an die Arbeitsplatte und stützen Sie sich mit einer Hand darauf ab.","Neigen Sie den Oberkörper etwas nach vorn und lassen Sie den anderen Arm locker nach unten hängen.","Bringen Sie den Arm durch leichtes Vor- und Zurückwiegen des Körpers ins Pendeln.","Der Arm bleibt dabei ganz locker; später dürfen die Pendel auch kleine Kreise werden."],"fehler":["Der Arm wird mit Muskelkraft geschwungen, statt locker zu pendeln.","Die Schulter wird zum Ohr hochgezogen.","Die Ausschläge werden so groß, dass es schmerzt."],"hinweise_praxis":"Nach einer Schulteroperation gilt das Nachbehandlungsschema des Operateurs (passiv, aktiv-assistiv, aktiv)."},
{"schluessel":"SH-02","version":"1.0.0","name":"Schulterblattstabilisation im Sitz (Skapula-Setting)","alltagsname":"Schultern nach hinten unten ziehen","region":"schulter","ziel":"stabilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":5,"taeglich":2},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Hände liegen locker auf den Oberschenkeln.","Ziehen Sie beide Schulterblätter sanft nach hinten und unten, als wollten Sie sie in die Gesäßtaschen stecken.","Halten Sie die Spannung 5 Sekunden und atmen Sie dabei ruhig weiter.","Lassen Sie danach wieder locker."],"fehler":["Die Schultern werden zu den Ohren hochgezogen.","Der Oberkörper lehnt sich zurück, das Hohlkreuz verstärkt sich.","Es wird mit großer Kraft gezogen statt sanft."],"hinweise_praxis":"Nach einer Schulteroperation gilt das Nachbehandlungsschema des Operateurs (passiv, aktiv-assistiv, aktiv)."},
{"schluessel":"SH-03","version":"1.0.0","name":"Schulterkreisen rückwärts","alltagsname":"Schultern nach hinten kreisen","region":"schulter","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"taeglich":3},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Hände liegen locker auf den Oberschenkeln.","Ziehen Sie beide Schultern langsam nach oben zu den Ohren.","Führen Sie sie dann nach hinten und unten, sodass ein großer, ruhiger Kreis entsteht.","Atmen Sie dabei ruhig weiter."],"fehler":["Der Kopf wird nach vorn geschoben.","Die Kreise sind klein und schnell statt groß und langsam."],"hinweise_praxis":"Nach einer Schulteroperation gilt das Nachbehandlungsschema des Operateurs (passiv, aktiv-assistiv, aktiv)."},
{"schluessel":"SH-04","version":"1.0.0","name":"Assistive Flexion mit Stab in Rückenlage","alltagsname":"Arme mit dem Stab über den Kopf führen","region":"schulter","ziel":"mobilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":["stab","bett"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":2},"anleitung":["Legen Sie sich auf den Rücken, etwa auf das Bett, und stellen Sie die Beine auf.","Fassen Sie einen Stab schulterbreit mit beiden Händen, die Arme liegen gestreckt vor dem Körper.","Führen Sie den Stab mit gestreckten Armen langsam über den Kopf nach hinten, so weit es angenehm geht.","Der beweglichere Arm hilft dabei dem anderen mit.","Führen Sie den Stab ebenso langsam zurück."],"fehler":["Das Hohlkreuz verstärkt sich, wenn die Arme über den Kopf gehen.","Die Ellbogen werden stark gebeugt.","Die Schultern werden zu den Ohren hochgezogen."],"hinweise_praxis":"Nach einer Schulteroperation gilt das Nachbehandlungsschema des Operateurs (passiv, aktiv-assistiv, aktiv)."},
{"schluessel":"SH-05","version":"1.0.0","name":"Assistive Außenrotation mit Stab in Rückenlage","alltagsname":"Arm mit dem Stab nach außen drehen","region":"schulter","ziel":"mobilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":["stab"],"hilfsmittel_optional":["handtuch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":2},"anleitung":["Legen Sie sich auf den Rücken und stellen Sie die Beine auf.","Beugen Sie beide Ellbogen rechtwinklig, die Oberarme liegen am Körper, und fassen Sie den Stab mit beiden Händen.","Schieben Sie mit dem Stab einen Unterarm langsam nach außen, der Ellbogen bleibt dabei am Körper.","Halten Sie kurz und führen Sie den Arm ebenso langsam zurück."],"fehler":["Der Ellbogen löst sich vom Körper.","Der Arm wird mit Schwung nach außen gedrückt."],"hinweise_praxis":"Nach einer Schulteroperation gilt das Nachbehandlungsschema des Operateurs (passiv, aktiv-assistiv, aktiv). Ein gefaltetes Handtuch unter dem Oberarm entlastet die Schulter."},
{"schluessel":"SH-06","version":"1.0.0","name":"Tischgleiten im Stand","alltagsname":"Arm auf dem Tisch nach vorn schieben","region":"schulter","ziel":"mobilitaet","ausgangsstellung":"stand","hilfsmittel":["tisch","handtuch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":2},"anleitung":["Stellen Sie sich dicht vor eine Arbeitsplatte oder einen hohen Tisch und legen Sie die Hand auf ein Handtuch auf der Platte.","Schieben Sie das Handtuch mit der Hand langsam nach vorn und beugen Sie den Oberkörper dabei aus der Hüfte mit.","Gehen Sie so weit, wie es angenehm ist, und halten Sie kurz.","Richten Sie sich danach langsam wieder auf und ziehen Sie den Arm zu sich heran."],"fehler":["Die Schulter wird zum Ohr hochgezogen.","Der Arm wird angehoben, statt auf dem Tisch geschoben zu werden."],"hinweise_praxis":"Nach einer Schulteroperation gilt das Nachbehandlungsschema des Operateurs (passiv, aktiv-assistiv, aktiv)."},
{"schluessel":"SH-07","version":"1.0.0","name":"Wandkrabbeln (Fingerleiter)","alltagsname":"Mit den Fingern die Wand hochwandern","region":"schulter","ziel":"mobilitaet","ausgangsstellung":"stand","hilfsmittel":["wand"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"taeglich":2},"anleitung":["Stellen Sie sich mit dem Gesicht zur Wand, etwa eine Unterarmlänge entfernt.","Legen Sie die Fingerspitzen einer Hand in Brusthöhe an die Wand.","Wandern Sie mit den Fingern langsam an der Wand nach oben, so weit es angenehm geht.","Wandern Sie ebenso langsam wieder nach unten."],"fehler":["Die Schulter wird zum Ohr hochgezogen.","Der Oberkörper weicht ins Hohlkreuz aus, statt den Arm zu heben."],"hinweise_praxis":"Nach einer Schulteroperation gilt das Nachbehandlungsschema des Operateurs (passiv, aktiv-assistiv, aktiv)."},
{"schluessel":"SH-08","version":"1.0.0","name":"Innenrotationsdehnung mit Handtuch","alltagsname":"Handtuch hinter dem Rücken hochziehen","region":"schulter","ziel":"dehnung","ausgangsstellung":"stand","hilfsmittel":["handtuch"],"niveau":2,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":5,"taeglich":1},"anleitung":["Nehmen Sie ein langes Handtuch in eine Hand und lassen Sie es über die Schulter hinter den Rücken hängen.","Greifen Sie das untere Ende mit der anderen Hand hinter dem Rücken.","Ziehen Sie das Handtuch mit der oberen Hand langsam nach oben, bis Sie an der unteren Schulter eine Dehnung spüren.","Halten Sie 5 Sekunden und lassen Sie die untere Hand langsam wieder sinken."],"fehler":["Der Oberkörper neigt sich zur Seite oder nach vorn.","Es wird ruckartig gezogen.","Die untere Schulter kippt nach vorn."]},
{"schluessel":"SH-09","version":"1.0.0","name":"Dehnung der hinteren Schulter (Cross-Body)","alltagsname":"Arm vor der Brust herüberziehen","region":"schulter","ziel":"dehnung","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl.","Führen Sie einen Arm in Schulterhöhe vor der Brust zur anderen Seite.","Fassen Sie den Arm mit der anderen Hand oberhalb des Ellbogens und ziehen Sie ihn sanft zur Brust, bis Sie hinten an der Schulter eine Dehnung spüren.","Halten Sie die Dehnung ruhig, die Schultern bleiben unten."],"fehler":["Der Oberkörper dreht sich mit.","Die Schulter wird zum Ohr hochgezogen."]},
{"schluessel":"SH-10","version":"1.0.0","name":"Isometrische Außenrotation an der Wand","alltagsname":"Handrücken gegen die Wand drücken","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["wand","handtuch"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":5,"taeglich":1},"anleitung":["Stellen Sie sich mit einer Seite dicht neben eine Wand.","Klemmen Sie ein gefaltetes Handtuch zwischen Ellbogen und Körper und beugen Sie den Ellbogen rechtwinklig, der Unterarm zeigt nach vorn.","Drücken Sie den Handrücken sanft gegen die Wand, ohne dass sich der Arm bewegt.","Halten Sie den Druck 5 Sekunden, atmen Sie weiter und lassen Sie langsam locker."],"fehler":["Der Ellbogen löst sich vom Körper.","Die Luft wird angehalten.","Es wird mit voller Kraft gedrückt."],"hinweise_praxis":"Mit geringer Kraft beginnen, etwa einem Drittel der möglichen Kraft; der Druck bleibt schmerzfrei."},
{"schluessel":"SH-11","version":"1.0.0","name":"Isometrische Innenrotation am Türrahmen","alltagsname":"Handfläche gegen den Türrahmen drücken","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["tuerrahmen"],"hilfsmittel_optional":["handtuch"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":5,"taeglich":1},"anleitung":["Stellen Sie sich an einen Türrahmen, der Ellbogen liegt am Körper und ist rechtwinklig gebeugt, der Unterarm zeigt nach vorn.","Legen Sie die Handinnenfläche an die Kante des Türrahmens.","Drücken Sie die Hand sanft gegen den Rahmen nach innen Richtung Bauch, ohne dass sich der Arm bewegt.","Halten Sie den Druck 5 Sekunden, atmen Sie weiter und lassen Sie langsam locker."],"fehler":["Der Ellbogen löst sich vom Körper.","Der Oberkörper dreht sich mit.","Die Luft wird angehalten."],"hinweise_praxis":"Mit geringer Kraft beginnen, etwa einem Drittel der möglichen Kraft; der Druck bleibt schmerzfrei. Ein gefaltetes Handtuch zwischen Ellbogen und Körper hilft, den Ellbogen am Platz zu halten."},
{"schluessel":"SH-12","version":"1.0.0","name":"Isometrische Abduktion an der Wand","alltagsname":"Arm seitlich gegen die Wand drücken","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["wand"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":5,"taeglich":1},"anleitung":["Stellen Sie sich mit einer Seite dicht neben eine Wand.","Beugen Sie den Ellbogen rechtwinklig und legen Sie den Unterarm vor den Bauch, der Ellbogen berührt die Wand.","Drücken Sie den Ellbogen sanft seitlich gegen die Wand, ohne dass sich der Arm bewegt.","Halten Sie den Druck 5 Sekunden, atmen Sie weiter und lassen Sie langsam locker."],"fehler":["Der Oberkörper neigt sich von der Wand weg.","Die Schulter wird zum Ohr hochgezogen.","Die Luft wird angehalten."],"hinweise_praxis":"Mit geringer Kraft beginnen, etwa einem Drittel der möglichen Kraft; der Druck bleibt schmerzfrei."},
{"schluessel":"SH-13","version":"1.0.0","name":"Außenrotation mit Theraband im Stand","alltagsname":"Unterarm gegen das Band nach außen drehen","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["theraband","handtuch"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12},"anleitung":["Befestigen Sie das Band in Ellbogenhöhe an einer Türklinke und stellen Sie sich seitlich dazu, der übende Arm ist von der Tür abgewandt.","Klemmen Sie ein gefaltetes Handtuch zwischen Ellbogen und Körper, beugen Sie den Ellbogen rechtwinklig und fassen Sie das Band.","Drehen Sie den Unterarm langsam gegen den Zug des Bandes nach außen, der Ellbogen bleibt am Handtuch.","Führen Sie den Arm ebenso langsam zurück."],"fehler":["Der Ellbogen löst sich vom Körper.","Der Oberkörper dreht sich mit.","Das Handgelenk knickt ab."],"hinweise_praxis":"Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“."},
{"schluessel":"SH-14","version":"1.0.0","name":"Innenrotation mit Theraband im Stand","alltagsname":"Unterarm gegen das Band nach innen drehen","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["theraband"],"hilfsmittel_optional":["handtuch"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12},"anleitung":["Befestigen Sie das Band in Ellbogenhöhe an einer Türklinke und stellen Sie sich seitlich dazu, der übende Arm ist der Tür zugewandt.","Beugen Sie den Ellbogen rechtwinklig, legen Sie ihn an den Körper und fassen Sie das Band.","Drehen Sie den Unterarm langsam gegen den Zug des Bandes nach innen zum Bauch, der Ellbogen bleibt am Körper.","Führen Sie den Arm ebenso langsam zurück."],"fehler":["Der Ellbogen löst sich vom Körper.","Der Oberkörper dreht sich mit."],"hinweise_praxis":"Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“. Ein gefaltetes Handtuch zwischen Ellbogen und Körper hilft, den Ellbogen am Platz zu halten."},
{"schluessel":"SH-15","version":"1.0.0","name":"Außenrotation in Seitlage","alltagsname":"In Seitlage den Unterarm nach oben drehen","region":"schulter","ziel":"kraft","ausgangsstellung":"seitlage","hilfsmittel":["hantel","handtuch"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12},"anleitung":["Legen Sie sich auf die Seite, der übende Arm liegt oben.","Klemmen Sie ein gefaltetes Handtuch zwischen Ellbogen und Körper und beugen Sie den Ellbogen rechtwinklig, der Unterarm liegt vor dem Bauch.","Drehen Sie den Unterarm mit dem Gewicht langsam nach oben, der Ellbogen bleibt am Handtuch.","Senken Sie den Unterarm ebenso langsam wieder ab."],"fehler":["Der Ellbogen löst sich vom Körper.","Der Oberkörper rollt nach hinten mit.","Der Unterarm fällt schnell zurück."],"hinweise_praxis":"Mit leichtem Gewicht beginnen, etwa einer kleinen Wasserflasche; die Last im Plan als Dosierung eintragen."},
{"schluessel":"SH-16","version":"1.0.0","name":"Armheben in der Schulterblattebene (Daumen oben)","alltagsname":"Arme schräg nach vorn heben","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["hantel"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Stellen Sie sich aufrecht hin und nehmen Sie in jede Hand ein leichtes Gewicht, etwa eine kleine Wasserflasche.","Lassen Sie die Arme hängen, die Daumen zeigen nach vorn.","Heben Sie die gestreckten Arme langsam schräg nach vorn, halb zwischen vorn und seitlich, bis auf Schulterhöhe.","Senken Sie die Arme ebenso langsam wieder ab."],"fehler":["Die Schultern werden zu den Ohren hochgezogen.","Der Oberkörper lehnt sich nach hinten.","Die Arme werden mit Schwung gehoben."],"hinweise_praxis":"Die Last im Plan als Dosierung eintragen; ohne Gewicht beginnen, wenn das Heben bis Schulterhöhe schon anstrengt."},
{"schluessel":"SH-17","version":"1.0.0","name":"Seitheben bis Schulterhöhe","alltagsname":"Arme seitlich heben","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["hantel"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Stellen Sie sich aufrecht hin und nehmen Sie in jede Hand ein leichtes Gewicht, etwa eine kleine Wasserflasche.","Heben Sie die Arme mit leicht gebeugten Ellbogen langsam seitlich an, bis sie auf Schulterhöhe sind.","Senken Sie die Arme ebenso langsam wieder ab."],"fehler":["Die Schultern werden zu den Ohren hochgezogen.","Die Arme werden mit Schwung gehoben.","Der Oberkörper lehnt sich nach hinten."],"hinweise_praxis":"Die Last im Plan als Dosierung eintragen; ohne Gewicht beginnen, wenn das Heben schon anstrengt."},
{"schluessel":"SH-18","version":"1.0.0","name":"Wand-Liegestütz","alltagsname":"Liegestütz an der Wand","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["wand"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Stellen Sie sich etwa eine Armlänge vor eine Wand und legen Sie die Hände in Schulterhöhe schulterbreit an die Wand.","Beugen Sie die Ellbogen langsam und bringen Sie den Oberkörper zur Wand, der Körper bleibt dabei gerade.","Drücken Sie sich ebenso langsam wieder zurück.","Atmen Sie beim Zurückdrücken aus."],"fehler":["Das Becken hängt durch oder knickt ein.","Der Kopf wird zur Wand geschoben.","Die Schultern werden zu den Ohren hochgezogen."],"hinweise_praxis":"Leichter mit kleinerem Abstand zur Wand, schwerer mit größerem."},
{"schluessel":"SH-19","version":"1.0.0","name":"Unterarmgleiten an der Wand (Serratus-Slide)","alltagsname":"Unterarme an der Wand hochschieben","region":"schulter","ziel":"stabilitaet","ausgangsstellung":"stand","hilfsmittel":["wand","handtuch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10},"anleitung":["Stellen Sie sich mit dem Gesicht zur Wand und legen Sie beide Unterarme senkrecht an die Wand, die Ellbogen etwas unter Schulterhöhe.","Legen Sie ein Handtuch unter die Unterarme, damit sie leicht gleiten.","Drücken Sie die Unterarme leicht gegen die Wand und schieben Sie sie langsam nach oben, so weit es angenehm geht.","Lassen Sie die Unterarme ebenso langsam wieder nach unten gleiten."],"fehler":["Die Schultern werden zu den Ohren hochgezogen.","Das Hohlkreuz verstärkt sich.","Die Unterarme lösen sich von der Wand."]},
{"schluessel":"SH-20","version":"1.0.0","name":"Einarmiges Rudern mit Abstützen","alltagsname":"Gewicht zum Körper ziehen","region":"schulter","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["tisch","hantel"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stützen Sie sich mit einer Hand auf die Arbeitsplatte und neigen Sie den geraden Oberkörper etwas nach vorn.","Nehmen Sie in die andere Hand ein leichtes Gewicht, der Arm hängt gestreckt nach unten.","Ziehen Sie den Ellbogen langsam nach hinten oben, bis die Hand etwa an der Hüfte ist.","Senken Sie das Gewicht langsam ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberkörper dreht sich auf.","Der Rücken wird rund.","Die Schulter wird zum Ohr hochgezogen."],"hinweise_praxis":"Die Last im Plan als Dosierung eintragen."},
{"schluessel":"SH-21","version":"1.0.0","name":"Rhythmische Stabilisation in Rückenlage","alltagsname":"Arm senkrecht halten, kleine Kreise","region":"schulter","ziel":"stabilitaet","ausgangsstellung":"rueckenlage","hilfsmittel":["bett"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken, etwa auf das Bett, und stellen Sie die Beine auf.","Strecken Sie einen Arm senkrecht zur Decke.","Zeichnen Sie mit der Hand kleine, langsame Kreise, der Arm bleibt gestreckt.","Wechseln Sie zwischendurch die Richtung der Kreise."],"fehler":["Die Schulter hebt sich von der Unterlage.","Die Kreise werden groß und schnell.","Der Ellbogen beugt sich."],"hinweise_praxis":"Im Hausbesuch auch mit leichten Stößen der Fachperson aus wechselnden Richtungen üben."},
{"schluessel":"SH-22","version":"1.0.0","name":"PNF-Diagonale mit Theraband","alltagsname":"Band schräg über den Körper ziehen","region":"schulter","ziel":"koordination","ausgangsstellung":"stand","hilfsmittel":["theraband"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stellen Sie sich aufrecht hin und stellen Sie einen Fuß auf ein Ende des Bandes.","Fassen Sie das andere Ende mit der Hand der Gegenseite, die Hand liegt vor der Hüfte über diesem Fuß.","Ziehen Sie das Band mit gestrecktem Arm schräg über den Körper nach oben und außen, bis die Hand über dem Kopf ist.","Führen Sie den Arm langsam auf demselben Weg zurück und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberkörper dreht oder neigt sich mit.","Der Arm wird mit Schwung gezogen.","Die Schulter wird zum Ohr hochgezogen."],"hinweise_praxis":"Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“. Den Bewegungsweg einmal gemeinsam führen, bevor allein geübt wird."},
{"schluessel":"EH-01","version":"1.0.0","name":"Ellenbogen beugen und strecken","alltagsname":"Arm beugen und strecken","region":"ellenbogen","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich aufrecht hin, die Arme hängen locker neben dem Körper, die Handflächen zeigen nach vorn.","Beugen Sie einen oder beide Ellbogen langsam, bis die Hand Richtung Schulter kommt.","Strecken Sie den Arm danach langsam wieder ganz.","Der Oberarm bleibt dabei ruhig neben dem Körper."],"fehler":["Der Oberarm wandert nach vorn, statt neben dem Körper zu bleiben.","Der Arm wird am Ende nicht ganz gestreckt.","Die Bewegung geht mit Schwung."],"hinweise_praxis":"Nach Ruhigstellung oder Operation gelten Bewegungsgrenzen nach ärztlicher Vorgabe."},
{"schluessel":"EH-02","version":"1.0.0","name":"Pro- und Supination","alltagsname":"Handfläche nach oben und unten drehen","region":"ellenbogen","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich an einen Tisch und legen Sie den Unterarm auf, der Ellbogen ist rechtwinklig gebeugt und liegt am Körper.","Drehen Sie die Handfläche langsam nach oben, so weit es angenehm geht.","Drehen Sie sie danach langsam nach unten, bis der Handrücken oben liegt.","Nur der Unterarm dreht sich, der Ellbogen bleibt am Körper."],"fehler":["Der Ellbogen wandert vom Körper weg, die Schulter dreht mit.","Die Drehung kommt aus dem Handgelenk statt aus dem Unterarm."]},
{"schluessel":"EH-03","version":"1.0.0","name":"Bizepscurl","alltagsname":"Gewicht zur Schulter beugen","region":"ellenbogen","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["hantel"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12},"anleitung":["Setzen Sie sich aufrecht hin und nehmen Sie in jede Hand eine Hantel oder eine Wasserflasche.","Lassen Sie die Arme neben dem Körper hängen, die Handflächen zeigen nach vorn.","Beugen Sie die Ellbogen langsam und führen Sie das Gewicht Richtung Schulter.","Senken Sie es langsam wieder ab, bis die Arme fast gestreckt sind."],"fehler":["Der Oberkörper schwingt nach hinten mit.","Die Ellbogen wandern nach vorn.","Das Gewicht fällt schnell nach unten, statt langsam abgesenkt zu werden."],"hinweise_praxis":"Das Gewicht steht in der Dosierung als Last, etwa „1 kg“ oder „0,5-l-Flasche“."},
{"schluessel":"EH-04","version":"1.0.0","name":"Trizepsstrecken mit Abstützen","alltagsname":"Arm nach hinten strecken","region":"ellenbogen","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["tisch","hantel"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12,"je_seite":true},"anleitung":["Stellen Sie sich vor einen Tisch und stützen Sie sich mit einer Hand darauf ab, der Rücken ist gerade nach vorn geneigt.","Nehmen Sie das Gewicht in die andere Hand und legen Sie den Oberarm eng an den Körper, der Ellbogen ist gebeugt.","Strecken Sie den Ellbogen langsam, bis der Arm gerade nach hinten zeigt; der Oberarm bleibt ruhig.","Beugen Sie den Arm langsam wieder und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberarm schwingt mit, statt ruhig am Körper zu bleiben.","Der Rücken wird rund.","Das Gewicht wird mit Schwung nach hinten geworfen."],"hinweise_praxis":"Das Gewicht steht in der Dosierung als Last, etwa „1 kg“; die stützende Hand gibt Halt und Gleichgewicht."},
{"schluessel":"EH-05","version":"1.0.0","name":"Exzentrische Handgelenksextension","alltagsname":"Gewicht langsam absenken","region":"ellenbogen","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["hantel"],"hilfsmittel_optional":["tisch"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":15,"taeglich":1},"anleitung":["Setzen Sie sich an einen Tisch und legen Sie den Unterarm so auf, dass die Hand über die Kante ragt, die Handfläche zeigt nach unten. Ohne Tisch liegt der Unterarm auf dem Oberschenkel, die Hand ragt über das Knie.","Nehmen Sie ein leichtes Gewicht in die Hand und heben Sie die Hand mit Hilfe der anderen Hand nach oben.","Lassen Sie die helfende Hand los und senken Sie das Gewicht ganz langsam ab, etwa 3 bis 4 Sekunden lang.","Heben Sie die Hand wieder mit Hilfe der anderen Hand an und beginnen Sie von vorn."],"fehler":["Das Gewicht wird aus eigener Kraft wieder hochgehoben statt mit der anderen Hand.","Das Absenken geht zu schnell.","Der Unterarm hebt von der Unterlage ab."],"hinweise_praxis":"Die Dosierung gilt für einen Arm; für beide Seiten im Plan „je Seite“ setzen. Ein leichter Belastungsschmerz während der Übung ist häufig, er sollte bis zum nächsten Tag abklingen. Gewicht als Last eintragen."},
{"schluessel":"EH-06","version":"1.0.0","name":"Dehnung der Handgelenkstrecker","alltagsname":"Handrücken sanft beugen","region":"ellenbogen","ziel":"dehnung","ausgangsstellung":"stand","hilfsmittel":[],"niveau":1,"dosierung":{"saetze":3,"dauer_s":30,"taeglich":1},"anleitung":["Stellen Sie sich aufrecht hin und strecken Sie einen Arm gerade nach vorn, die Handfläche zeigt nach unten.","Beugen Sie das Handgelenk, sodass die Finger nach unten zeigen.","Ziehen Sie mit der anderen Hand den Handrücken sanft zu sich, bis Sie oben am Unterarm eine Dehnung spüren.","Halten Sie die Dehnung ruhig und atmen Sie weiter."],"fehler":["Der Ellbogen wird gebeugt.","Es wird ruckartig oder kräftig gezogen.","Die Schulter zieht nach oben."],"hinweise_praxis":"Die Dosierung gilt für einen Arm; für beide Seiten im Plan „je Seite“ setzen. Kribbeln in den Fingern ist kein Dehngefühl."},
{"schluessel":"EH-07","version":"1.0.0","name":"Handgelenk beugen und strecken","alltagsname":"Hand auf und ab bewegen","region":"hand","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"hilfsmittel_optional":["tisch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich an einen Tisch und legen Sie den Unterarm so auf, dass die Hand über die Kante ragt. Ohne Tisch liegt der Unterarm auf dem Oberschenkel, die Hand ragt über das Knie.","Heben Sie die Hand langsam nach oben, so weit es angenehm geht.","Senken Sie sie danach langsam nach unten, so weit es angenehm geht.","Der Unterarm bleibt dabei ruhig liegen, die Finger sind locker."],"fehler":["Der Unterarm hebt von der Unterlage ab.","Die Finger werden zur festen Faust geschlossen.","Die Bewegung geht mit Schwung."]},
{"schluessel":"EH-08","version":"1.0.0","name":"Faustschluss und Finger spreizen","alltagsname":"Faust machen, Finger spreizen","region":"hand","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":3},"anleitung":["Setzen Sie sich bequem hin und legen Sie den Unterarm auf dem Oberschenkel oder einem Tisch ab.","Schließen Sie die Hand langsam zu einer lockeren Faust, der Daumen liegt außen.","Öffnen Sie die Hand danach und spreizen Sie die Finger weit auseinander.","Wechseln Sie ruhig zwischen Faust und gespreizten Fingern."],"fehler":["Die Faust wird mit voller Kraft zusammengedrückt.","Die Finger werden beim Öffnen nicht ganz gestreckt."],"hinweise_praxis":"Bei geschwollener Hand die Übung mit hochgelagertem Arm ausführen lassen."},
{"schluessel":"EH-09","version":"1.0.0","name":"Sehnengleitübungen","alltagsname":"Finger in fünf Stellungen führen","region":"hand","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":5,"taeglich":3},"anleitung":["Setzen Sie sich bequem hin, stützen Sie den Ellbogen auf und strecken Sie die Finger gerade nach oben.","Beugen Sie nur die vorderen Fingergelenke zu einer Hakenfaust, strecken Sie die Finger wieder und schließen Sie die Hand dann zur vollen Faust.","Beugen Sie danach nur die Fingergrundgelenke, die Finger bleiben gestreckt wie eine Tischplatte.","Machen Sie zuletzt eine gerade Faust: Die Fingerkuppen berühren unten die Handfläche, die vordersten Gelenke bleiben gestreckt.","Kehren Sie nach jeder Stellung zur geraden Hand zurück und halten Sie jede Stellung kurz."],"fehler":["Die Stellungen werden mit Kraft erzwungen statt ruhig erreicht.","Das Handgelenk beugt sich mit.","Bei der Hakenfaust beugen sich auch die Fingergrundgelenke."],"hinweise_praxis":"Die Dosierung gilt je Stellung. Die fünf Stellungen einmal gemeinsam einüben; nach Operation an Sehnen der Hand gilt das Schema der Handchirurgie."},
{"schluessel":"EH-10","version":"1.0.0","name":"Griffkraft mit Softball","alltagsname":"Weichen Ball zusammendrücken","region":"hand","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["ball"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10,"halten_s":3,"taeglich":1},"anleitung":["Setzen Sie sich bequem hin und nehmen Sie einen weichen Ball in die Hand.","Drücken Sie den Ball mit der ganzen Hand zusammen, so fest es angenehm ist.","Halten Sie den Druck so lange wie im Plan angegeben und atmen Sie dabei weiter.","Lassen Sie langsam los und öffnen Sie die Hand ganz."],"fehler":["Das Handgelenk knickt beim Drücken ab.","Die Luft wird angehalten.","Es wird so fest gedrückt, dass es schmerzt."],"hinweise_praxis":"Ein Schaumstoffball oder eine zusammengerollte Socke genügt; die Härte des Balls als Last eintragen."},
{"schluessel":"EH-11","version":"1.0.0","name":"Handtuch auswringen","alltagsname":"Handtuch auswringen","region":"hand","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["handtuch"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht hin und fassen Sie ein zusammengerolltes Handtuch mit beiden Händen vor dem Körper.","Drehen Sie die Hände gegeneinander, als wollten Sie das Handtuch auswringen.","Lösen Sie die Spannung und drehen Sie danach in die andere Richtung.","Arbeiten Sie langsam und nur mit so viel Kraft, wie es angenehm ist."],"fehler":["Die Schultern ziehen nach oben.","Es wird ruckartig gedreht.","Die Handgelenke knicken stark ab."],"hinweise_praxis":"Belastet Handgelenk und Daumensattelgelenk deutlich; erst üben, wenn diese Belastung erlaubt ist."},
{"schluessel":"EH-12","version":"1.0.0","name":"Daumen-Finger-Opposition","alltagsname":"Daumen tippt jede Fingerkuppe an","region":"hand","ziel":"koordination","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":4,"taeglich":2},"anleitung":["Setzen Sie sich bequem hin, die Hand ist locker geöffnet.","Tippen Sie mit der Daumenkuppe nacheinander die Kuppen von Zeigefinger, Mittelfinger, Ringfinger und kleinem Finger an.","Jede Fingerkuppe zählt als eine Wiederholung; nach dem kleinen Finger ist ein Durchgang geschafft.","Achten Sie darauf, dass sich die Kuppen berühren und jedes Mal ein kleines „O“ entsteht."],"fehler":["Der Daumen berührt die Finger seitlich statt mit der Kuppe.","Die Bewegung wird hastig statt genau ausgeführt."]},
{"schluessel":"HU-01","version":"1.0.0","name":"Hüftabduktion in Seitlage","alltagsname":"In Seitlage Bein abspreizen","region":"huefte","ziel":"kraft","ausgangsstellung":"seitlage","hilfsmittel":["kissen"],"hilfsmittel_optional":["matte"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Legen Sie sich auf die Seite, der Kopf liegt auf dem unteren Arm oder einem Kissen.","Das obere Bein ist gestreckt, das untere dürfen Sie für einen sicheren Halt leicht beugen.","Heben Sie das obere Bein langsam ein Stück an, die Fußspitze zeigt nach vorn.","Senken Sie das Bein langsam ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Bein wandert nach vorn, statt zur Seite gehoben zu werden.","Das Becken kippt nach hinten.","Die Fußspitze dreht nach oben."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier betrifft das vor allem den seitlichen Zugang: Abspreizen gegen die Schwerkraft ist dort oft erst nach einigen Wochen erlaubt. In den Pausen hält ein Kissen zwischen den Knien das obere Bein aus der Adduktion."},
{"schluessel":"HU-02","version":"1.0.0","name":"Muschel (Clamshell)","alltagsname":"In Seitlage Knie öffnen","region":"huefte","ziel":"kraft","ausgangsstellung":"seitlage","hilfsmittel":[],"hilfsmittel_optional":["theraband","matte"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":12,"je_seite":true},"anleitung":["Legen Sie sich auf die Seite, Hüfte und Knie sind leicht gebeugt, die Füße liegen aufeinander.","Öffnen Sie das obere Knie langsam wie eine Muschel, die Füße bleiben zusammen.","Das Becken bleibt dabei ruhig und kippt nicht nach hinten.","Schließen Sie das Knie langsam und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Becken dreht sich nach hinten mit.","Die Füße lösen sich voneinander.","Das Knie fällt schnell zurück."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Mit Band über den Knien steigern; die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“."},
{"schluessel":"HU-03","version":"1.0.0","name":"Hüftadduktion in Seitlage","alltagsname":"Unteres Bein anheben","region":"huefte","ziel":"kraft","ausgangsstellung":"seitlage","hilfsmittel":[],"hilfsmittel_optional":["kissen","matte"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Legen Sie sich auf die Seite und stützen Sie den Kopf auf den unteren Arm.","Stellen Sie das obere Bein angewinkelt vor dem unteren Bein auf oder legen Sie es auf ein Kissen.","Heben Sie das untere, gestreckte Bein langsam ein kleines Stück an.","Senken Sie es langsam ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Becken kippt nach hinten.","Das Bein wird mit Schwung gehoben."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier: Das vor dem Körper aufgestellte obere Bein ist gebeugt und adduziert; ist es nach hinterem Zugang das operierte, die Übung erst nach Freigabe."},
{"schluessel":"HU-04","version":"1.0.0","name":"Hüftabduktion im Stand","alltagsname":"Bein seitlich abspreizen","region":"huefte","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"hilfsmittel_optional":["gewichtsmanschette"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stellen Sie sich seitlich neben einen Stuhl und halten Sie sich mit einer Hand an der Lehne fest.","Spreizen Sie das äußere Bein langsam zur Seite ab, die Fußspitze zeigt nach vorn.","Der Oberkörper bleibt aufrecht und neigt sich nicht zur Gegenseite.","Führen Sie das Bein langsam zurück und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberkörper neigt sich zur Seite.","Die Fußspitze dreht nach außen, das Bein geht nach vorn statt zur Seite.","Das Bein wird mit Schwung gehoben."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier vor allem der seitliche Zugang. Steigerung über eine Gewichtsmanschette am Knöchel; die Last im Plan als Dosierung eintragen."},
{"schluessel":"HU-05","version":"1.0.0","name":"Hüftextension im Stand","alltagsname":"Bein nach hinten führen","region":"huefte","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"hilfsmittel_optional":["gewichtsmanschette"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stellen Sie sich hinter einen Stuhl und halten Sie sich mit beiden Händen an der Lehne fest.","Führen Sie ein gestrecktes Bein langsam nach hinten, so weit es ohne Hohlkreuz geht.","Der Oberkörper bleibt aufrecht, das Bein bleibt gestreckt und die Fußspitze zeigt nach vorn.","Führen Sie das Bein langsam zurück und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Es entsteht ein Hohlkreuz, statt die Hüfte zu strecken.","Der Oberkörper kippt weit nach vorn.","Das Bein dreht nach außen."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier vor allem der vordere Zugang: das Bein nur bis knapp hinter die Senkrechte führen und nicht nach außen drehen."},
{"schluessel":"HU-06","version":"1.0.0","name":"Knieheben im Stand","alltagsname":"Knie im Stand anheben","region":"huefte","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stellen Sie sich seitlich neben eine Stuhllehne und halten Sie sich mit einer Hand fest.","Heben Sie ein Knie langsam nach vorn oben, bis der Oberschenkel fast waagerecht ist.","Der Oberkörper bleibt dabei aufrecht.","Setzen Sie den Fuß langsam ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberkörper lehnt sich nach hinten.","Das Standbein knickt ein.","Der Fuß wird schnell abgesetzt."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier: Beim hinteren Zugang das Knie nur bis unter 90° Beugung heben."},
{"schluessel":"HU-07","version":"1.0.0","name":"Knieheben im Sitz","alltagsname":"Im Sitz Knie anheben","region":"huefte","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl und halten Sie sich seitlich am Sitz fest.","Heben Sie ein Knie langsam an, sodass der Fuß vom Boden abhebt.","Halten Sie kurz und setzen Sie den Fuß langsam wieder ab.","Der Oberkörper bleibt aufrecht und lehnt sich nicht zurück."],"fehler":["Der Oberkörper lehnt sich nach hinten.","Der Fuß fällt schnell zurück auf den Boden."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier: Im Sitz ist die Hüfte schon etwa 90° gebeugt; beim hinteren Zugang ist das Knieheben im Sitz deshalb häufig für einige Wochen nicht erlaubt, dann das Knieheben im Stand wählen oder höher sitzen."},
{"schluessel":"HU-08","version":"1.0.0","name":"Abduktion im Sitz gegen Band","alltagsname":"Knie gegen das Band öffnen","region":"huefte","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl","theraband"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":12},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl und legen Sie das Band als Schlinge knapp oberhalb der Knie um beide Oberschenkel.","Die Füße stehen hüftbreit auf dem Boden.","Drücken Sie die Knie langsam gegen den Zug des Bandes auseinander.","Führen Sie die Knie langsam wieder zusammen, ohne dass das Band ganz locker wird."],"fehler":["Der Oberkörper lehnt sich nach hinten.","Die Füße heben vom Boden ab.","Die Knie fallen schnell zurück."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier vor allem der seitliche Zugang. Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“."},
{"schluessel":"HU-09","version":"1.0.0","name":"Adduktion im Sitz gegen Kissen","alltagsname":"Knie gegen ein Kissen drücken","region":"huefte","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl","kissen"],"hilfsmittel_optional":["ball"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":5,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl und klemmen Sie ein gefaltetes Kissen oder einen weichen Ball zwischen die Knie.","Drücken Sie die Knie gegen das Kissen und halten Sie die Spannung 5 Sekunden.","Atmen Sie dabei ruhig weiter.","Lassen Sie langsam locker und machen Sie eine kurze Pause."],"fehler":["Die Luft wird angehalten.","Der Oberkörper beugt sich nach vorn."]},
{"schluessel":"HU-10","version":"1.0.0","name":"Hüftextension in Bauchlage","alltagsname":"In Bauchlage gestrecktes Bein heben","region":"huefte","ziel":"kraft","ausgangsstellung":"bauchlage","hilfsmittel":["kissen"],"hilfsmittel_optional":["matte"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Legen Sie sich auf den Bauch, die Stirn ruht auf einem flachen Kissen oder auf den Händen.","Spannen Sie das Gesäß an und heben Sie ein gestrecktes Bein ein kleines Stück von der Unterlage.","Das Becken bleibt dabei auf der Unterlage liegen.","Senken Sie das Bein langsam ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Bein wird zu hoch gehoben, es entsteht ein Hohlkreuz.","Das Becken dreht sich mit auf.","Das Knie wird gebeugt."],"hinweise_praxis":"Bauchlage ist für viele Hochbetagte nicht möglich (Atmung, Herz, Endoprothese); dann die Hüftextension im Stand wählen. Ein flaches Kissen unter dem Bauch verhindert ein Hohlkreuz. Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand."},
{"schluessel":"HU-11","version":"1.0.0","name":"Seitschritte mit Band","alltagsname":"Mit Band seitwärts gehen","region":"huefte","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["theraband","tisch"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Legen Sie das Band als Schlinge um beide Unterschenkel, knapp über den Knöcheln.","Stellen Sie sich mit dem Gesicht zur Arbeitsplatte, die Knie sind leicht gebeugt.","Gehen Sie 10 kleine Schritte zur Seite an der Arbeitsplatte entlang, das Band bleibt dabei gespannt.","Gehen Sie danach die gleiche Zahl Schritte in die andere Richtung zurück."],"fehler":["Der Oberkörper schwankt von Seite zu Seite.","Die Füße kommen ganz zusammen, das Band wird locker.","Die Fußspitzen drehen nach außen."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier vor allem der seitliche Zugang. Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“; die Hände bleiben zur Sicherheit an der Arbeitsplatte oder in ihrer Nähe."},
{"schluessel":"HU-12","version":"1.0.0","name":"Seitliches Aufsteigen auf eine Stufe","alltagsname":"Seitlich auf die Stufe steigen","region":"huefte","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stufe"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stellen Sie sich seitlich neben die unterste Stufe und halten Sie sich am Geländer fest.","Setzen Sie den Fuß, der der Stufe näher ist, ganz auf die Stufe.","Steigen Sie mit der Kraft dieses Beins hinauf, bis es gestreckt ist; das andere Bein bleibt in der Luft.","Senken Sie das freie Bein langsam wieder zum Boden und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Knie des oberen Beins fällt nach innen.","Das untere Bein stößt sich kräftig vom Boden ab.","Der Oberkörper neigt sich weit zur Seite."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier vor allem der seitliche Zugang und die erlaubte Belastung des Beins auf der Stufe."},
{"schluessel":"HU-13","version":"1.0.0","name":"Einbeinstand mit Beckenkontrolle","alltagsname":"Auf einem Bein stehen, Becken gerade","region":"huefte","ziel":"stabilitaet","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":20,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich seitlich neben eine Stuhllehne und halten Sie sich mit einer Hand leicht fest.","Verlagern Sie das Gewicht auf das Bein neben dem Stuhl und heben Sie den anderen Fuß etwas vom Boden ab.","Halten Sie das Becken dabei waagerecht, es sinkt auf der Seite des freien Beins nicht ab.","Stehen Sie ruhig, so lange es im Plan steht, und wechseln Sie dann die Seite."],"fehler":["Das Becken sinkt auf der Seite des freien Beins ab.","Der Oberkörper neigt sich über das Standbein.","Die Hand trägt das Gewicht."],"hinweise_praxis":"Belastung des Standbeins nach ärztlicher Vorgabe; nach Hüftendoprothese erst mit voller Belastungsfreigabe. Steigerung: die Hand nur noch über der Lehne halten."},
{"schluessel":"HU-14","version":"1.0.0","name":"Hüftbeugerdehnung an der Bettkante","alltagsname":"Bein über die Bettkante hängen lassen","region":"huefte","ziel":"dehnung","ausgangsstellung":"rueckenlage","hilfsmittel":["bett"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken, nah an die Längsseite eines festen Bettes.","Fassen Sie das Knie des Beins, das zur Bettmitte liegt, mit beiden Händen und ziehen Sie es zur Brust.","Lassen Sie das äußere Bein locker über die Bettkante nach unten hängen, bis Sie vorn an der Hüfte eine Dehnung spüren.","Halten Sie die Dehnung ruhig und holen Sie danach zuerst das hängende Bein zurück aufs Bett."],"fehler":["Das gebeugte Knie ist zu weit von der Brust entfernt, es entsteht ein Hohlkreuz.","Das hängende Bein wird aktiv nach unten gedrückt."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier: Das zur Brust gezogene Bein ist über 90° gebeugt (hinterer Zugang), das hängende in Streckung (vorderer Zugang); nach Hüftendoprothese erst nach Freigabe. Nur auf einem festen Bett; das Zurückholen des Beins vorher gemeinsam üben."},
{"schluessel":"HU-15","version":"1.0.0","name":"Hüftbeugerdehnung in Schrittstellung","alltagsname":"Im Ausfallschritt Becken nach vorn","region":"huefte","ziel":"dehnung","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich neben eine Stuhllehne und halten Sie sich mit einer Hand fest.","Machen Sie einen großen Schritt nach vorn, beide Fußspitzen zeigen nach vorn.","Schieben Sie das Becken langsam nach vorn, bis Sie vorn an der Hüfte des hinteren Beins eine Dehnung spüren.","Halten Sie den Oberkörper aufrecht und die Dehnung ruhig, dann wechseln Sie die Seite."],"fehler":["Es entsteht ein Hohlkreuz, statt das Becken nach vorn zu schieben.","Der Oberkörper neigt sich nach vorn.","Das vordere Knie schiebt weit über die Fußspitze."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier vor allem der vordere Zugang: Die Dehnung bringt das hintere Bein in Streckung; erst nach Freigabe."},
{"schluessel":"HU-16","version":"1.0.0","name":"Gesäßdehnung im Sitz (Piriformis)","alltagsname":"Bein überschlagen, nach vorn neigen","region":"huefte","ziel":"dehnung","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl und legen Sie einen Fußknöchel auf das andere Knie.","Lassen Sie das obere Knie locker zur Seite sinken.","Neigen Sie den geraden Oberkörper langsam nach vorn, bis Sie im Gesäß eine Dehnung spüren.","Halten Sie die Dehnung ruhig und wechseln Sie dann die Seite."],"fehler":["Der Rücken wird rund, statt aus der Hüfte nach vorn zu neigen.","Es wird gewippt.","Das obere Knie wird mit der Hand nach unten gedrückt."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier: Nach Hüftendoprothese erst nach ärztlicher Freigabe, denn das Vorneigen beugt die Hüfte über 90°."},
{"schluessel":"HU-17","version":"1.0.0","name":"Gesäßdehnung in Rückenlage","alltagsname":"Knie zur Gegenschulter ziehen","region":"huefte","ziel":"dehnung","ausgangsstellung":"rueckenlage","hilfsmittel":[],"hilfsmittel_optional":["matte"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken und stellen Sie beide Beine an.","Fassen Sie ein Knie mit beiden Händen.","Ziehen Sie das Knie langsam schräg Richtung gegenüberliegende Schulter, bis Sie im Gesäß eine Dehnung spüren.","Halten Sie die Dehnung ruhig, der Kopf bleibt auf der Unterlage."],"fehler":["Das Becken hebt von der Unterlage ab.","Es wird ruckartig gezogen.","Der Kopf hebt ab."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier: Nach Hüftendoprothese erst nach ärztlicher Freigabe, denn Knie zur Gegenschulter verbindet Beugung über 90° mit Adduktion - beim hinteren Zugang die typische Luxationsstellung."},
{"schluessel":"HU-18","version":"1.0.0","name":"Hüftrotation im Sitz","alltagsname":"Unterschenkel nach innen und außen schwenken","region":"huefte","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Füße stehen hüftbreit auf dem Boden.","Heben Sie einen Fuß etwas vom Boden ab, das Knie bleibt an seinem Platz.","Schwenken Sie den Unterschenkel langsam nach außen und wieder nach innen, so weit es angenehm geht.","Setzen Sie den Fuß ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Knie wandert mit, statt an seinem Platz zu bleiben.","Das Becken rutscht auf dem Stuhl hin und her.","Es wird mit Schwung geschwenkt."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier: Den Fuß nach außen zu schwenken ist Innenrotation der gebeugten Hüfte, beim hinteren Zugang dann nur nach innen schwenken."},
{"schluessel":"HU-19","version":"1.0.0","name":"Ausfallschritt rückwärts mit Halt","alltagsname":"Großer Schritt nach hinten","region":"huefte","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":8,"je_seite":true},"anleitung":["Stellen Sie sich neben eine Stuhllehne und halten Sie sich mit einer Hand fest.","Machen Sie mit einem Bein einen großen Schritt nach hinten und setzen Sie den Fußballen auf.","Senken Sie sich gerade nach unten, so tief es sicher geht; das vordere Knie bleibt über dem Fuß.","Drücken Sie sich mit dem vorderen Bein zurück in den Stand und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberkörper kippt nach vorn.","Das vordere Knie fällt nach innen.","Der Schritt ist zu kurz, das vordere Knie schiebt weit über die Fußspitze."],"hinweise_praxis":"Nach Hüftendoprothese gelten Bewegungsgrenzen und Belastung nach OP-Bericht und ärztlicher Vorgabe; häufig für einige Wochen: beim hinteren Zugang keine Beugung über 90°, keine Adduktion über die Mittellinie und keine Innenrotation, beim vorderen Zugang keine Streckung über die Neutralstellung mit Außenrotation, beim seitlichen Zugang kein Abspreizen gegen Widerstand. Hier: Das hintere Bein kommt in Streckung (vorderer Zugang), das vordere in tiefe Beugung (hinterer Zugang); Schrittlänge und Tiefe nach Vorgabe."},
{"schluessel":"KN-01","version":"1.0.0","name":"Kniestreckung im Sitz (Long Arc Quad)","alltagsname":"Im Sitz das Knie strecken","region":"knie","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"hilfsmittel_optional":["gewichtsmanschette"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10,"halten_s":3,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, beide Füße stehen flach auf dem Boden.","Strecken Sie ein Knie langsam, bis das Bein fast gerade ist.","Ziehen Sie die Fußspitze zu sich und halten Sie das Bein 3 Sekunden.","Senken Sie den Fuß langsam ab und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Der Oberkörper lehnt sich nach hinten.","Das Bein fällt schnell zurück, statt langsam abgesenkt zu werden."],"hinweise_praxis":"Steigerung über eine Gewichtsmanschette am Knöchel; die Last im Plan als Dosierung eintragen."},
{"schluessel":"KN-02","version":"1.0.0","name":"Kniebeugung im Sitz","alltagsname":"Fuß unter den Stuhl ziehen","region":"knie","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":3},"anleitung":["Setzen Sie sich vorn auf die Stuhlkante, beide Füße stehen auf dem Boden.","Schieben Sie einen Fuß langsam nach hinten unter den Stuhl, so weit es angenehm geht.","Bleiben Sie dort einen Moment und schieben Sie den Fuß wieder nach vorn."],"fehler":["Das Gesäß rutscht nach vorn, statt das Knie zu beugen.","Die Ferse hebt früh ab und das Knie beugt kaum."]},
{"schluessel":"KN-03","version":"1.0.0","name":"Fußgleiten im Sitz","alltagsname":"Fuß auf dem Handtuch vor und zurück","region":"knie","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl","handtuch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":15,"taeglich":3},"anleitung":["Setzen Sie sich auf einen Stuhl und legen Sie ein Handtuch unter einen Fuß.","Schieben Sie den Fuß auf dem Handtuch langsam nach vorn, bis das Knie fast gestreckt ist.","Ziehen Sie den Fuß danach so weit zurück, wie es angenehm geht.","Bewegen Sie sich ruhig und ohne Schwung."],"fehler":["Der Fuß wird angehoben statt geschoben.","Der Oberkörper schaukelt mit."]},
{"schluessel":"KN-04","version":"1.0.0","name":"Passive Kniestreckung, Ferse hochgelagert","alltagsname":"Ferse hochlegen, Knie hängen lassen","region":"knie","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl","handtuch"],"niveau":1,"dosierung":{"saetze":1,"dauer_s":240,"taeglich":3},"anleitung":["Setzen Sie sich auf einen Stuhl und legen Sie die Ferse auf einen zweiten Stuhl.","Legen Sie ein gefaltetes Handtuch unter die Ferse, nicht unter das Knie.","Lassen Sie das Knie locker durchhängen und atmen Sie ruhig weiter.","Bleiben Sie so lange in dieser Lage, wie es im Plan steht."],"fehler":["Das Knie wird aktiv durchgedrückt, statt locker zu hängen.","Ein Kissen liegt unter dem Knie und hält es gebeugt."],"hinweise_praxis":"Nach Knieendoprothese keine Dauerlagerung mit Kissen unter dem Knie: Das Kissen nur für die Übung verwenden, sonst droht ein Streckdefizit."},
{"schluessel":"KN-05","version":"1.0.0","name":"Patellamobilisation","alltagsname":"Kniescheibe sanft verschieben","region":"knie","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich mit ausgestreckten Beinen aufs Bett oder Sofa und lehnen Sie den Rücken an, das Bein liegt gestreckt und ganz locker.","Fassen Sie die Kniescheibe mit Daumen und Zeigefinger am oberen und unteren Rand.","Schieben Sie sie sanft nach oben und unten, danach nach rechts und links.","Bewegen Sie jede Richtung 10-mal, ohne auf die Kniescheibe zu drücken."],"fehler":["Die Oberschenkelmuskulatur ist angespannt, die Kniescheibe bewegt sich kaum.","Es wird auf die Kniescheibe gedrückt, statt sie zu schieben."],"hinweise_praxis":"Erst nach abgeschlossener Wundheilung, nicht über der Narbe."},
{"schluessel":"KN-06","version":"1.0.0","name":"Endgradige Kniestreckung mit Band (TKE)","alltagsname":"Knie gegen das Band durchstrecken","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["theraband","tuerrahmen"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12,"je_seite":true},"anleitung":["Befestigen Sie das Band in Kniehöhe an einem festen Gegenstand, etwa am Türrahmen.","Stellen Sie sich mit dem Gesicht dazu und legen Sie das Band hinter ein Knie.","Beugen Sie das Knie leicht und strecken Sie es dann gegen den Zug des Bandes ganz.","Lassen Sie das Knie langsam wieder leicht beugen."],"fehler":["Das Knie wird ruckartig nach hinten durchgedrückt.","Das Becken weicht nach hinten aus, statt das Knie zu strecken."],"hinweise_praxis":"Die Bandstärke als Last in der Dosierung eintragen, etwa „Theraband gelb“."},
{"schluessel":"KN-07","version":"1.0.0","name":"Mini-Kniebeuge mit Halt","alltagsname":"Mit Halt leicht in die Knie gehen","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Stellen Sie sich vor die Arbeitsplatte und halten Sie sich mit beiden Händen fest.","Stellen Sie die Füße hüftbreit auseinander.","Gehen Sie langsam ein kleines Stück in die Knie, als wollten Sie sich setzen.","Richten Sie sich wieder auf, ohne die Knie ganz durchzudrücken."],"fehler":["Die Knie schieben weit über die Fußspitzen.","Die Knie fallen nach innen.","Die Fersen heben ab."]},
{"schluessel":"KN-08","version":"1.0.0","name":"Kniebeuge zum Stuhl","alltagsname":"Bis zum Stuhl absenken und wieder hoch","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Stellen Sie sich mit dem Rücken vor einen Stuhl, die Füße stehen hüftbreit.","Schieben Sie das Gesäß nach hinten und senken Sie sich langsam ab, bis es den Sitz berührt.","Setzen Sie sich nicht ab, sondern drücken Sie sich gleich wieder in den Stand.","Strecken Sie die Arme dabei nach vorn, wenn es das Gleichgewicht erleichtert."],"fehler":["Die Person lässt sich auf den Stuhl fallen.","Die Knie fallen nach innen.","Der Oberkörper kippt weit nach vorn."]},
{"schluessel":"KN-09","version":"1.0.0","name":"Kniebeuge an der Wand (Wall Slide)","alltagsname":"An der Wand in die Knie gleiten","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["wand"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Lehnen Sie sich mit dem Rücken an eine Wand, die Füße stehen etwa eine Fußlänge davor.","Gleiten Sie mit dem Rücken langsam an der Wand nach unten, bis die Knie leicht gebeugt sind.","Halten Sie kurz und schieben Sie sich wieder nach oben."],"fehler":["Die Knie fallen nach innen.","Das Gesäß löst sich von der Wand."]},
{"schluessel":"KN-10","version":"1.0.0","name":"Wandsitz","alltagsname":"An der Wand sitzen","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["wand"],"niveau":3,"dosierung":{"saetze":3,"dauer_s":30},"anleitung":["Lehnen Sie sich mit dem Rücken an eine Wand.","Gehen Sie mit den Füßen ein Stück nach vorn und gleiten Sie nach unten, bis die Knie etwa rechtwinklig sind.","Halten Sie diese Stellung und atmen Sie ruhig weiter.","Schieben Sie sich danach an der Wand wieder nach oben."],"fehler":["Die Knie schieben über die Fußspitzen hinaus.","Die Luft wird angehalten."],"hinweise_praxis":"Die Tiefe nach Beschwerden wählen; rechtwinklig ist das Ziel, nicht der Anfang."},
{"schluessel":"KN-11","version":"1.0.0","name":"Aufsteigen auf eine Stufe (Step-up)","alltagsname":"Auf die Stufe steigen","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stufe"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stellen Sie sich vor eine Stufe und halten Sie sich bei Bedarf am Geländer fest.","Setzen Sie einen Fuß ganz auf die Stufe.","Steigen Sie mit der Kraft dieses Beins hinauf, bis Sie auf der Stufe stehen.","Steigen Sie rückwärts wieder hinunter, zuerst mit dem anderen Bein."],"fehler":["Das Knie fällt beim Hochsteigen nach innen.","Das untere Bein stößt sich kräftig vom Boden ab."]},
{"schluessel":"KN-12","version":"1.0.0","name":"Exzentrischer Step-down","alltagsname":"Langsam von der Stufe absenken","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stufe"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":8,"je_seite":true},"anleitung":["Stellen Sie sich auf die unterste Stufe und halten Sie sich am Geländer fest.","Stellen Sie ein Bein frei über die Kante nach vorn.","Beugen Sie das Standbein langsam, bis die Ferse des freien Beins den Boden berührt.","Drücken Sie sich mit dem Standbein wieder nach oben."],"fehler":["Das Becken kippt zur Seite des freien Beins.","Das Standbein wird schnell gebeugt statt langsam.","Das Knie des Standbeins fällt nach innen."]},
{"schluessel":"KN-13","version":"1.0.0","name":"Kniebeuge in Schrittstellung mit Halt (Split Squat)","alltagsname":"In Schrittstellung absenken","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":8,"je_seite":true},"anleitung":["Stellen Sie sich neben eine Stuhllehne und halten Sie sich mit einer Hand fest.","Machen Sie einen großen Schritt nach vorn, die hintere Ferse hebt ab.","Senken Sie sich gerade nach unten, bis das hintere Knie fast den Boden berührt.","Drücken Sie sich wieder nach oben und wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das vordere Knie schiebt weit über die Fußspitze.","Der Oberkörper kippt nach vorn.","Die Schritte sind zu kurz."]},
{"schluessel":"KN-14","version":"1.0.0","name":"Kniebeugung im Stand (Beinbeuger)","alltagsname":"Ferse Richtung Po heben","region":"knie","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"hilfsmittel_optional":["gewichtsmanschette"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stellen Sie sich hinter einen Stuhl und halten Sie sich an der Lehne fest.","Heben Sie eine Ferse langsam Richtung Po, das Knie zeigt dabei nach unten.","Senken Sie den Fuß langsam wieder ab.","Wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Knie wandert nach vorn.","Der Oberkörper kippt nach vorn, das Hohlkreuz verstärkt sich."],"hinweise_praxis":"Steigerung über eine Gewichtsmanschette am Knöchel; die Last im Plan als Dosierung eintragen."},
{"schluessel":"KN-15","version":"1.0.0","name":"Beinbeuger in Bauchlage","alltagsname":"In Bauchlage die Ferse zum Po","region":"knie","ziel":"kraft","ausgangsstellung":"bauchlage","hilfsmittel":["matte"],"hilfsmittel_optional":["gewichtsmanschette"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Legen Sie sich auf den Bauch, die Stirn ruht auf einem flachen Kissen oder auf den Händen.","Beugen Sie ein Knie langsam, bis der Unterschenkel senkrecht steht.","Senken Sie den Unterschenkel langsam wieder ab.","Wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Becken hebt sich von der Unterlage.","Der Unterschenkel fällt am Ende schnell zurück."],"hinweise_praxis":"Bauchlage ist für viele Hochbetagte nicht möglich (Atmung, Herz, Endoprothese); dann die Übung im Stand wählen."},
{"schluessel":"KN-16","version":"1.0.0","name":"Dehnung der ischiokruralen Muskulatur im Sitz","alltagsname":"Bein ausstrecken, nach vorn neigen","region":"knie","ziel":"dehnung","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich vorn auf die Stuhlkante.","Strecken Sie ein Bein nach vorn aus, die Ferse steht auf dem Boden, die Fußspitze zeigt nach oben.","Neigen Sie den geraden Oberkörper langsam nach vorn, bis Sie hinten am Oberschenkel eine Dehnung spüren.","Halten Sie die Dehnung ruhig und atmen Sie weiter."],"fehler":["Der Rücken wird rund, statt aus der Hüfte nach vorn zu neigen.","Es wird gewippt."]},
{"schluessel":"KN-17","version":"1.0.0","name":"Dehnung der ischiokruralen Muskulatur mit Handtuch","alltagsname":"In Rückenlage das Bein mit dem Handtuch heben","region":"knie","ziel":"dehnung","ausgangsstellung":"rueckenlage","hilfsmittel":["handtuch","matte"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Legen Sie sich auf den Rücken und legen Sie ein Handtuch um eine Fußsohle.","Halten Sie die Enden des Handtuchs mit beiden Händen.","Ziehen Sie das gestreckte Bein langsam nach oben, bis Sie hinten am Bein eine Dehnung spüren.","Halten Sie die Dehnung ruhig, das andere Bein bleibt auf der Unterlage liegen."],"fehler":["Das Knie des gehobenen Beins wird gebeugt.","Der Kopf hebt von der Unterlage ab."]},
{"schluessel":"KN-18","version":"1.0.0","name":"Quadrizepsdehnung im Stand","alltagsname":"Im Stand die Ferse zum Po ziehen","region":"knie","ziel":"dehnung","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"hilfsmittel_optional":["handtuch"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich an eine Stuhllehne und halten Sie sich mit einer Hand fest.","Beugen Sie ein Knie und fassen Sie den Fuß mit der Hand derselben Seite; reicht sie nicht, legen Sie ein Handtuch um den Fuß.","Ziehen Sie die Ferse sanft Richtung Po, bis Sie vorn am Oberschenkel eine Dehnung spüren.","Halten Sie die Knie nebeneinander und den Oberkörper aufrecht."],"fehler":["Das Hohlkreuz verstärkt sich.","Das gebeugte Knie wandert nach vorn oder zur Seite."]},
{"schluessel":"KN-19","version":"1.0.0","name":"Einbeinige Mini-Kniebeuge mit Halt","alltagsname":"Auf einem Bein leicht in die Knie gehen","region":"knie","ziel":"stabilitaet","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":8,"je_seite":true},"anleitung":["Stellen Sie sich vor die Arbeitsplatte und halten Sie sich mit beiden Händen leicht fest.","Heben Sie einen Fuß etwas vom Boden ab.","Beugen Sie das Standbein langsam ein kleines Stück und strecken Sie es wieder.","Achten Sie darauf, dass das Knie über dem Fuß bleibt."],"fehler":["Das Knie fällt nach innen.","Das Becken sinkt auf der Seite des freien Beins ab.","Die Hände tragen das Gewicht."]},
{"schluessel":"FU-01","version":"1.0.0","name":"Fersenheben im Stand mit Halt","alltagsname":"Auf die Zehenspitzen stellen","region":"fuss","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":[10,15]},"anleitung":["Stellen Sie sich vor die Arbeitsplatte und halten Sie sich mit beiden Händen fest.","Stellen Sie die Füße hüftbreit auseinander.","Heben Sie langsam beide Fersen, bis Sie auf den Zehenballen stehen.","Senken Sie die Fersen langsam wieder ab."],"fehler":["Das Gewicht rutscht auf die Außenkanten der Füße.","Die Fersen fallen schnell zurück.","Die Hände ziehen den Körper nach oben."]},
{"schluessel":"FU-02","version":"1.0.0","name":"Einbeiniges Fersenheben mit Halt","alltagsname":"Auf einem Bein auf die Zehen","region":"fuss","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true},"anleitung":["Stellen Sie sich vor die Arbeitsplatte und halten Sie sich mit beiden Händen leicht fest.","Heben Sie einen Fuß vom Boden ab, indem Sie das Knie beugen.","Heben Sie die Ferse des Standbeins langsam, so hoch es geht, und senken Sie sie langsam wieder ab.","Wechseln Sie nach allen Wiederholungen die Seite."],"fehler":["Das Gewicht rutscht auf die Außenkante des Fußes.","Die Hände ziehen den Körper nach oben.","Das Knie des Standbeins beugt sich."]},
{"schluessel":"FU-03","version":"1.0.0","name":"Fersenheben im Sitz","alltagsname":"Im Sitz die Fersen heben","region":"fuss","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":15,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, beide Füße stehen flach auf dem Boden.","Heben Sie beide Fersen langsam an, die Zehenballen bleiben am Boden.","Senken Sie die Fersen langsam wieder ab."],"fehler":["Die Fersen fallen schnell zurück.","Der Oberkörper schaukelt mit."],"hinweise_praxis":"Steigerung, indem die Hände auf den Knien leicht nach unten drücken."},
{"schluessel":"FU-04","version":"1.0.0","name":"Vorfußheben im Stand mit Halt","alltagsname":"Zehen und Vorfuß anheben","region":"fuss","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10},"anleitung":["Stellen Sie sich vor die Arbeitsplatte und halten Sie sich mit beiden Händen fest.","Heben Sie langsam beide Fußspitzen an, bis Sie auf den Fersen stehen.","Senken Sie die Fußspitzen langsam wieder ab."],"fehler":["Das Gesäß schiebt sich nach hinten.","Die Fußspitzen fallen schnell zurück.","Die Hände ziehen den Körper nach vorn."]},
{"schluessel":"FU-05","version":"1.0.0","name":"Wadendehnung an der Wand, Knie gestreckt","alltagsname":"Wade an der Wand dehnen","region":"fuss","ziel":"dehnung","ausgangsstellung":"stand","hilfsmittel":["wand"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich mit dem Gesicht zur Wand und stützen Sie sich mit beiden Händen in Schulterhöhe ab.","Machen Sie mit einem Bein einen großen Schritt nach hinten, beide Fußspitzen zeigen nach vorn.","Beugen Sie das vordere Knie und schieben Sie das Becken zur Wand, das hintere Knie bleibt gestreckt und die Ferse am Boden.","Halten Sie die Dehnung in der hinteren Wade ruhig und atmen Sie weiter."],"fehler":["Die hintere Ferse hebt ab.","Der hintere Fuß dreht nach außen.","Es wird gewippt."]},
{"schluessel":"FU-06","version":"1.0.0","name":"Soleusdehnung an der Wand, Knie gebeugt","alltagsname":"Tiefe Wade dehnen","region":"fuss","ziel":"dehnung","ausgangsstellung":"stand","hilfsmittel":["wand"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich mit dem Gesicht zur Wand und stützen Sie sich mit beiden Händen ab.","Stellen Sie einen Fuß einen kleinen Schritt nach hinten, beide Fußspitzen zeigen nach vorn.","Beugen Sie langsam beide Knie, die hintere Ferse bleibt am Boden.","Halten Sie die Dehnung tief in der hinteren Wade ruhig und atmen Sie weiter."],"fehler":["Die hintere Ferse hebt ab.","Das hintere Knie bleibt gestreckt, dann dehnt sich vor allem die obere Wade.","Es wird gewippt."]},
{"schluessel":"FU-07","version":"1.0.0","name":"Zehenkrallen mit Handtuch","alltagsname":"Handtuch mit den Zehen heranziehen","region":"fuss","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl","handtuch"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich auf einen Stuhl und legen Sie ein Handtuch flach vor Ihre Füße.","Stellen Sie einen Fuß auf das hintere Ende des Handtuchs, die Ferse bleibt am Boden.","Ziehen Sie das Handtuch mit den Zehen Stück für Stück zu sich heran.","Schieben Sie das Handtuch danach wieder glatt und wechseln Sie nach allen Wiederholungen den Fuß."],"fehler":["Die Ferse hebt vom Boden ab.","Der Fuß wird als Ganzes zurückgezogen, statt mit den Zehen zu greifen."]},
{"schluessel":"FU-08","version":"1.0.0","name":"Kurzer Fuß (Fußgewölbe aufrichten)","alltagsname":"Fußgewölbe aufbauen","region":"fuss","ziel":"stabilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":1,"wiederholungen":10,"halten_s":5,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Füße stehen flach auf dem Boden.","Ziehen Sie den Zehenballen sanft Richtung Ferse, ohne die Zehen einzukrallen, sodass sich das Fußgewölbe leicht hebt.","Halten Sie die Spannung 5 Sekunden und lassen Sie wieder locker.","Zehen und Ferse bleiben die ganze Zeit am Boden."],"fehler":["Die Zehen krallen sich ein.","Der Fuß kippt auf die Außenkante.","Die Ferse hebt ab."],"hinweise_praxis":"Die Bewegung ist klein und braucht meist eine gemeinsame Anleitung im Hausbesuch, anfangs mit Blick auf den Fuß."},
{"schluessel":"FU-09","version":"1.0.0","name":"Sprunggelenk gegen Theraband im Sitz","alltagsname":"Fuß gegen das Band bewegen","region":"fuss","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl","theraband"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":12,"je_seite":true},"anleitung":["Setzen Sie sich auf einen Stuhl, strecken Sie ein Bein nach vorn und stellen Sie die Ferse auf den Boden.","Legen Sie das Band um den Vorfuß und halten Sie die Enden mit beiden Händen fest.","Drücken Sie die Fußspitze langsam gegen den Zug des Bandes nach unten und lassen Sie sie langsam zurückkommen.","Üben Sie danach ebenso gegen das Band nach innen und nach außen, jede Richtung mit der Zahl aus dem Plan.","Wechseln Sie nach allen Richtungen das Bein."],"fehler":["Das Bein dreht mit, statt nur den Fuß zu bewegen.","Der Fuß schnellt mit dem Band zurück."],"hinweise_praxis":"Die Bandstärke steht in der Dosierung als Last, etwa „Theraband gelb“. Die Wiederholungen gelten je Richtung. Für das Heben der Fußspitze das Band vorn an einem Tischbein befestigen."},
{"schluessel":"FU-10","version":"1.0.0","name":"Fußalphabet","alltagsname":"Buchstaben mit dem Fuß schreiben","region":"fuss","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":1,"wiederholungen":1,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich auf einen Stuhl und strecken Sie ein Bein etwas nach vorn, die Ferse bleibt am Boden.","Schreiben Sie mit der großen Zehe langsam alle Buchstaben des Alphabets in die Luft.","Die Bewegung kommt aus dem Sprunggelenk, das Bein bleibt ruhig.","Wechseln Sie danach das Bein."],"fehler":["Das ganze Bein bewegt sich mit, statt nur der Fuß.","Die Buchstaben werden klein und hastig."]},
{"schluessel":"FU-11","version":"1.0.0","name":"Fußsohlenrollen mit Ball","alltagsname":"Fußsohle über einen Ball rollen","region":"fuss","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl","ball"],"niveau":1,"dosierung":{"saetze":1,"dauer_s":60,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich auf einen Stuhl und legen Sie einen kleinen Ball, etwa einen Tennisball, vor einen Fuß.","Stellen Sie den Fuß auf den Ball und rollen Sie ihn langsam unter der Fußsohle von der Ferse bis zu den Zehen.","Drücken Sie nur so fest, wie es angenehm ist.","Wechseln Sie nach der Zeit aus dem Plan den Fuß."],"fehler":["Es wird zu fest gedrückt.","Der Ball rollt nur unter der Ferse oder nur unter den Zehen."],"hinweise_praxis":"Bei herabgesetztem Gefühl an den Füßen den Druck vorher gemeinsam prüfen und die Haut danach ansehen."},
{"schluessel":"FU-12","version":"1.0.0","name":"Dehnung der Plantarfaszie im Sitz","alltagsname":"Zehen Richtung Schienbein ziehen","region":"fuss","ziel":"dehnung","ausgangsstellung":"sitz","hilfsmittel":["stuhl","handtuch"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":30,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich auf einen Stuhl, strecken Sie ein Bein nach vorn und stellen Sie die Ferse auf den Boden.","Legen Sie ein Handtuch um den Vorfuß und halten Sie die Enden mit beiden Händen fest.","Ziehen Sie die Zehen mit dem Handtuch sanft Richtung Schienbein. Wer das Bein gut überschlagen kann, legt den Fuß stattdessen auf das andere Knie und zieht die Zehen mit der Hand.","Halten Sie die Dehnung in der Fußsohle ruhig und atmen Sie weiter.","Wechseln Sie danach die Seite."],"fehler":["Es wird ruckartig gezogen.","Nur die große Zehe wird gezogen."],"hinweise_praxis":"Gut vor den ersten Schritten am Morgen. Das Bild zeigt die Variante mit dem Handtuch; sie braucht kein Überschlagen des Beins."},
{"schluessel":"GG-01","version":"1.0.0","name":"Geschlossener Stand mit Halt","alltagsname":"Füße eng zusammen stehen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":20,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte und legen Sie beide Hände darauf.","Stellen Sie die Füße eng nebeneinander, sodass sich die Innenkanten fast berühren.","Stehen Sie aufrecht, schauen Sie geradeaus und halten Sie die Stellung ruhig.","Lassen Sie die Hände nur so locker aufliegen, wie Sie sicher stehen, und greifen Sie bei Unsicherheit sofort fest zu."],"fehler":["Die Hände tragen das Gewicht, statt nur aufzuliegen.","Der Blick geht zu den Füßen.","Die Knie werden durchgedrückt oder die Luft wird angehalten."],"hinweise_praxis":"Steigerung von 10 auf 30 Sekunden, danach mit leichterem Halt (eine Hand, Fingerspitzen)."},
{"schluessel":"GG-02","version":"1.0.0","name":"Semitandemstand","alltagsname":"Einen Fuß halb vor den anderen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":20,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte und legen Sie beide Hände darauf.","Stellen Sie einen Fuß halb vor den anderen, sodass seine Ferse neben der Mitte des anderen Fußes steht und sich beide Füße berühren.","Stehen Sie aufrecht, schauen Sie geradeaus und halten Sie die Stellung ruhig.","Wechseln Sie danach den vorderen Fuß und greifen Sie bei Unsicherheit sofort fest zu."],"fehler":["Die Füße stehen auseinander, statt sich zu berühren.","Die Hände tragen das Gewicht, statt nur aufzuliegen.","Der Oberkörper weicht zur Seite aus."],"hinweise_praxis":"Steigerung von 10 auf 30 Sekunden, danach mit leichterem Halt."},
{"schluessel":"GG-03","version":"1.0.0","name":"Tandemstand","alltagsname":"Füße voreinander stellen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":10,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte und legen Sie beide Hände darauf.","Setzen Sie einen Fuß direkt vor den anderen, sodass die Ferse die Zehen des hinteren Fußes berührt.","Schauen Sie geradeaus und halten Sie die Stellung ruhig, das Gewicht liegt auf beiden Füßen.","Wechseln Sie danach den vorderen Fuß und greifen Sie bei Unsicherheit sofort fest zu."],"fehler":["Die Füße stehen versetzt nebeneinander statt auf einer Linie.","Der Blick geht zu den Füßen.","Die Hüfte knickt zur Seite ab."],"hinweise_praxis":"Gelingt der Stand noch nicht ruhig, zuerst den Semitandemstand üben. Steigerung bis 30 Sekunden."},
{"schluessel":"GG-04","version":"1.0.0","name":"Einbeinstand mit Halt","alltagsname":"Mit Halt auf einem Bein stehen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":10,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte und legen Sie beide Hände darauf.","Verlagern Sie das Gewicht auf ein Bein und heben Sie den anderen Fuß ein kleines Stück vom Boden ab.","Stehen Sie aufrecht, das Knie des Standbeins bleibt locker und wird nicht durchgedrückt.","Stellen Sie den Fuß ab, sobald Sie wackeln, und wechseln Sie nach den Durchgängen das Bein."],"fehler":["Das Becken sinkt auf der Seite des angehobenen Beins ab.","Der Oberkörper lehnt sich weit zum Standbein.","Das Knie des Standbeins wird durchgedrückt."],"hinweise_praxis":"Steigerung von 10 auf 30 Sekunden, danach mit leichterem Halt."},
{"schluessel":"GG-05","version":"1.0.0","name":"Einbeinstand ohne Halt","alltagsname":"Frei auf einem Bein stehen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":3,"dosierung":{"saetze":3,"dauer_s":10,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte, die Hände liegen zunächst darauf.","Heben Sie einen Fuß ein kleines Stück vom Boden ab.","Lösen Sie die Hände und halten Sie sie dicht über der Arbeitsplatte, damit Sie sofort wieder zugreifen können.","Stellen Sie den Fuß ab, sobald Sie wackeln, und wechseln Sie nach den Durchgängen das Bein."],"fehler":["Die Hände entfernen sich von der Arbeitsplatte.","Das Becken sinkt auf der Seite des angehobenen Beins ab.","Die Luft wird angehalten."],"hinweise_praxis":"Nur mit Halt in Reichweite und einmal gemeinsam geübt. Ein Stuhl im Rücken ist für Ängstliche sinnvoll."},
{"schluessel":"GG-06","version":"1.0.0","name":"Gewichtsverlagerung vor und zurück","alltagsname":"Gewicht auf Zehen und Fersen verlagern","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte, legen Sie beide Hände darauf und stellen Sie die Füße hüftbreit.","Verlagern Sie Ihr Gewicht langsam nach vorn auf die Fußballen, ohne die Fersen abzuheben.","Verlagern Sie es danach langsam nach hinten auf die Fersen, ohne die Zehen abzuheben.","Bewegen Sie den Körper dabei gerade wie ein Brett und nur so weit, wie Sie sicher stehen."],"fehler":["Die Bewegung kommt aus der Hüfte, der Oberkörper knickt nach vorn.","Die Fersen oder die Zehen heben ab.","Die Knie werden gebeugt."]},
{"schluessel":"GG-07","version":"1.0.0","name":"Gewichtsverlagerung seitlich","alltagsname":"Gewicht von Bein zu Bein verlagern","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte, legen Sie beide Hände darauf und stellen Sie die Füße hüftbreit.","Verlagern Sie Ihr Gewicht langsam auf ein Bein, bis sich der andere Fuß leicht anfühlt.","Verlagern Sie es danach ebenso langsam auf das andere Bein.","Halten Sie den Oberkörper aufrecht und beide Füße am Boden; bei Unsicherheit greifen Sie fester zu."],"fehler":["Der Oberkörper neigt sich zur Seite, statt das Becken zu verschieben.","Ein Fuß hebt vom Boden ab.","Die Knie werden durchgedrückt."]},
{"schluessel":"GG-08","version":"1.0.0","name":"Seitwärtsgehen","alltagsname":"Seitwärts an der Arbeitsplatte entlang","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"gehen","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Räumen Sie den Weg frei, stellen Sie sich mit dem Gesicht zur Küchenarbeitsplatte und legen Sie beide Hände darauf.","Machen Sie einen Schritt zur Seite und ziehen Sie den anderen Fuß nach, ohne die Füße zu überkreuzen.","Gehen Sie so 10 Schritte an der Arbeitsplatte entlang, die Hände gleiten mit.","Gehen Sie danach in die andere Richtung zurück und schauen Sie dabei geradeaus."],"fehler":["Die Füße werden überkreuzt.","Die Fußspitzen drehen nach außen.","Der Oberkörper neigt sich in die Schrittrichtung."]},
{"schluessel":"GG-09","version":"1.0.0","name":"Tandemgang","alltagsname":"Fuß vor Fuß gehen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"gehen","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an die Küchenarbeitsplatte und legen Sie eine Hand darauf.","Setzen Sie einen Fuß direkt vor den anderen, sodass die Ferse die Zehen des hinteren Fußes berührt.","Gehen Sie so langsam 10 Schritte an der Arbeitsplatte entlang, die Hand gleitet mit; bei Unsicherheit bleiben Sie stehen und halten sich fest.","Drehen Sie sich am Ende in kleinen Schritten um und gehen Sie mit der anderen Hand an der Platte zurück."],"fehler":["Die Füße landen versetzt nebeneinander statt auf einer Linie.","Der Blick geht zu den Füßen.","Die Schritte werden hastig."]},
{"schluessel":"GG-10","version":"1.0.0","name":"Rückwärtsgehen","alltagsname":"Rückwärts gehen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"gehen","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an die Küchenarbeitsplatte, legen Sie eine Hand darauf und prüfen Sie, ob der Weg hinter Ihnen frei ist.","Gehen Sie langsam 10 Schritte rückwärts und setzen Sie dabei zuerst die Fußballen auf.","Bleiben Sie aufrecht und lassen Sie die Hand an der Platte mitgleiten.","Gehen Sie danach vorwärts zurück zum Anfang."],"fehler":["Der Oberkörper beugt sich nach vorn.","Die Füße schlurfen über den Boden.","Die Schritte werden zu groß."]},
{"schluessel":"GG-11","version":"1.0.0","name":"Fersengang","alltagsname":"Auf den Fersen gehen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"gehen","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an die Küchenarbeitsplatte und legen Sie eine Hand darauf.","Ziehen Sie die Fußspitzen hoch, sodass Sie nur noch auf den Fersen stehen.","Gehen Sie so 10 kleine Schritte an der Arbeitsplatte entlang, die Hand gleitet mit.","Setzen Sie die Füße flach ab, sobald Sie unsicher werden, und gehen Sie danach normal zurück."],"fehler":["Das Gesäß schiebt sich nach hinten, der Oberkörper kippt nach vorn.","Die Fußspitzen sinken zwischendurch ab."]},
{"schluessel":"GG-12","version":"1.0.0","name":"Zehengang","alltagsname":"Auf den Zehenspitzen gehen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"gehen","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an die Küchenarbeitsplatte und legen Sie eine Hand darauf.","Stellen Sie sich auf die Zehenspitzen.","Gehen Sie so 10 kleine Schritte an der Arbeitsplatte entlang, ohne die Fersen abzusetzen.","Setzen Sie die Fersen ab, sobald Sie unsicher werden, und gehen Sie danach normal zurück."],"fehler":["Die Fersen sinken zwischendurch ab.","Die Knie werden stark gebeugt.","Der Oberkörper kippt nach vorn."]},
{"schluessel":"GG-13","version":"1.0.0","name":"Gehen mit Kopfdrehen","alltagsname":"Beim Gehen nach links und rechts schauen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"gehen","hilfsmittel":[],"hilfsmittel_optional":["wand"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Gehen Sie in einem freien Flur dicht an einer Wand entlang, damit Sie sich jederzeit abstützen können.","Drehen Sie beim Gehen den Kopf langsam abwechselnd nach links und nach rechts, als würden Sie sich umschauen.","Gehen Sie so etwa 10 Schritte in Ihrem normalen Tempo und schauen Sie danach wieder geradeaus.","Bleiben Sie stehen und stützen Sie sich an der Wand ab, wenn Ihnen schwindelig wird."],"fehler":["Die Person bleibt beim Kopfdrehen stehen oder wird sehr langsam.","Der Gang weicht zur Seite ab.","Der ganze Oberkörper dreht mit statt nur der Kopf."],"hinweise_praxis":"Mit langsamen, kleinen Kopfdrehungen beginnen. Nimmt Schwindel deutlich zu, die Übung zurückstellen."},
{"schluessel":"GG-14","version":"1.0.0","name":"Achtergang","alltagsname":"In einer Acht gehen","region":"ganzkoerper","ziel":"koordination","ausgangsstellung":"gehen","hilfsmittel":["stuhl"],"niveau":3,"dosierung":{"wiederholungen":3,"taeglich":1},"anleitung":["Stellen Sie zwei feste Stühle mit etwa drei Schritten Abstand auf und räumen Sie den Weg um sie herum frei.","Gehen Sie in Ihrem normalen Tempo in einer Acht um die beiden Stühle herum.","Gehen Sie die Kurven in ruhigen Schritten und schauen Sie in die Richtung, in die Sie gehen.","Fassen Sie bei Unsicherheit an eine Stuhllehne und gehen Sie langsamer."],"fehler":["Die Kurven werden mit vielen kleinen Trippelschritten gegangen.","Der Blick geht zu den Füßen.","Das Tempo wird zu schnell."],"hinweise_praxis":"Nur mit Halt in Reichweite und einmal gemeinsam geübt. Ein Stuhl im Rücken ist für Ängstliche sinnvoll."},
{"schluessel":"GG-15","version":"1.0.0","name":"Ausfallschritt vor und zurück","alltagsname":"Großer Schritt nach vorn und zurück","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an die Küchenarbeitsplatte und legen Sie eine Hand darauf.","Machen Sie mit einem Bein einen großen Schritt nach vorn und beugen Sie dabei das vordere Knie leicht.","Drücken Sie sich mit dem vorderen Bein ab und stellen Sie den Fuß zurück neben den anderen.","Bleiben Sie aufrecht, halten Sie sich bei Unsicherheit fester und wechseln Sie nach allen Wiederholungen das Bein."],"fehler":["Das vordere Knie fällt nach innen.","Der Oberkörper kippt nach vorn.","Der Schritt bleibt so klein, dass kaum Gewicht auf das vordere Bein kommt."]},
{"schluessel":"GG-16","version":"1.0.0","name":"Uhrschritte","alltagsname":"Schritte in alle Richtungen","region":"ganzkoerper","ziel":"koordination","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":3,"dosierung":{"saetze":2,"wiederholungen":5,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an die Küchenarbeitsplatte und legen Sie eine Hand darauf.","Stellen Sie sich vor, Sie stehen in der Mitte eines Zifferblatts, und verlagern Sie das Gewicht auf das Bein an der Platte.","Tippen Sie mit dem äußeren Fuß nacheinander nach vorn, zur Seite und nach hinten auf den Boden und kommen Sie jedes Mal zurück in die Mitte.","Stellen Sie den Fuß bei Unsicherheit sofort ab; drehen Sie sich danach um und üben Sie mit dem anderen Bein."],"fehler":["Das Gewicht wandert auf das tippende Bein.","Das Knie des Standbeins wird durchgedrückt.","Der Oberkörper dreht sich mit."],"hinweise_praxis":"Nur mit Halt in Reichweite und einmal gemeinsam geübt. Ein Stuhl im Rücken ist für Ängstliche sinnvoll."},
{"schluessel":"GG-17","version":"1.0.0","name":"Reichen nach vorn im Stand","alltagsname":"Im Stand nach vorn greifen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an die Küchenarbeitsplatte, legen Sie eine Hand darauf und stellen Sie die Füße hüftbreit.","Heben Sie den anderen Arm gestreckt nach vorn auf Schulterhöhe.","Greifen Sie langsam so weit nach vorn, wie Sie sicher stehen, ohne einen Schritt zu machen und ohne die Fersen abzuheben.","Kommen Sie langsam zurück in den aufrechten Stand."],"fehler":["Die Fersen heben ab oder ein Fuß macht einen Schritt.","Der Oberkörper dreht sich auf, statt nach vorn zu reichen.","Die Hand an der Arbeitsplatte zieht den Körper mit."]},
{"schluessel":"GG-18","version":"1.0.0","name":"Stand auf weicher Unterlage","alltagsname":"Auf einem Kissen stehen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["kissen","tisch"],"niveau":3,"dosierung":{"saetze":3,"dauer_s":20,"taeglich":1},"anleitung":["Legen Sie ein festes Kissen oder eine doppelt gefaltete Decke dicht vor die Küchenarbeitsplatte auf einen Boden, auf dem es nicht rutscht.","Halten Sie sich mit beiden Händen an der Arbeitsplatte fest und steigen Sie mit beiden Füßen darauf.","Stehen Sie aufrecht, schauen Sie geradeaus und halten Sie die Stellung ruhig.","Lösen Sie die Hände nur, wenn Sie sicher stehen, und steigen Sie mit Halt wieder herunter."],"fehler":["Das Kissen rutscht auf dem Boden.","Der Blick geht zu den Füßen.","Die Knie werden durchgedrückt."],"hinweise_praxis":"Nur mit Halt in Reichweite und einmal gemeinsam geübt. Ein Stuhl im Rücken ist für Ängstliche sinnvoll. Auf glatten Fliesen eine rutschfeste Matte unterlegen."},
{"schluessel":"GG-19","version":"1.0.0","name":"Einbeinstand mit Zusatzaufgabe (Dual Task)","alltagsname":"Auf einem Bein stehen und rückwärts zählen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":3,"dosierung":{"saetze":3,"dauer_s":20,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte und legen Sie beide Hände leicht darauf.","Heben Sie einen Fuß ein kleines Stück vom Boden ab.","Zählen Sie dabei laut in Dreierschritten rückwärts, etwa von 100 an, oder zählen Sie Tiere, Städte oder Vornamen auf.","Stellen Sie den Fuß ab, sobald Sie wackeln, und wechseln Sie nach den Durchgängen das Bein."],"fehler":["Das Zählen stockt, sobald das Gleichgewicht schwierig wird.","Die Hände stützen sich fest ab.","Das Becken sinkt auf der Seite des angehobenen Beins ab."],"hinweise_praxis":"Nur mit Halt in Reichweite und einmal gemeinsam geübt. Ein Stuhl im Rücken ist für Ängstliche sinnvoll. Erst, wenn der Einbeinstand ohne Zusatzaufgabe sicher gelingt."},
{"schluessel":"GG-20","version":"1.0.0","name":"Blickstabilisation (VOR ×1)","alltagsname":"Einen Punkt anschauen, den Kopf drehen","region":"hws","ziel":"koordination","ausgangsstellung":"sitz","hilfsmittel":["stuhl","alltagsgegenstand"],"niveau":2,"dosierung":{"saetze":2,"dauer_s":30,"taeglich":3},"anleitung":["Setzen Sie sich auf einen Stuhl und kleben Sie einen Zettel mit einem großen Buchstaben in Augenhöhe an die Wand, etwa einen Meter vor Ihnen.","Schauen Sie auf den Buchstaben und drehen Sie den Kopf zügig, aber nur ein kleines Stück nach links und rechts.","Der Buchstabe soll dabei scharf bleiben; wird er unscharf, drehen Sie langsamer.","Leichter Schwindel darf kurz auftreten; machen Sie dann eine Pause, bis er abgeklungen ist."],"fehler":["Der Blick löst sich vom Buchstaben.","Der Oberkörper dreht mit.","Die Kopfbewegung wird so groß, dass der Buchstabe verschwimmt."],"hinweise_praxis":"Schwindelbeschwerden nur nach Befund. Die Symptome können während der Übung kurz zunehmen, das vorher erklären."},
{"schluessel":"AF-01","version":"1.0.0","name":"Sit-to-Stand mit Armhilfe","alltagsname":"Mit Armen vom Stuhl aufstehen","region":"ganzkoerper","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":3,"wiederholungen":[5,10],"taeglich":1},"anleitung":["Setzen Sie sich vorn auf einen stabilen Stuhl, die Füße stehen hüftbreit und etwas hinter den Knien.","Stützen Sie die Hände auf die Armlehnen oder neben sich auf die Sitzfläche.","Neigen Sie den Oberkörper nach vorn, bis die Nase über den Zehen ist.","Drücken Sie sich mit Beinen und Armen hoch, bis Sie aufrecht stehen.","Setzen Sie sich langsam wieder hin, die Hände stützen dabei mit."],"fehler":["Der Oberkörper bleibt hinten, die Person kommt nur mit Schwung hoch.","Die Knie fallen beim Aufstehen nach innen.","Die Person lässt sich auf den Stuhl fallen."],"hinweise_praxis":"Der Stuhl steht fest, am besten an der Wand. Ein höherer Sitz oder ein Kissen erleichtert den Anfang."},
{"schluessel":"AF-02","version":"1.0.0","name":"Sit-to-Stand ohne Armhilfe","alltagsname":"Ohne Hände aufstehen","region":"ganzkoerper","ziel":"kraft","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":10,"taeglich":1},"anleitung":["Setzen Sie sich vorn auf einen stabilen Stuhl, die Füße stehen hüftbreit und etwas hinter den Knien.","Verschränken Sie die Arme vor der Brust.","Neigen Sie den Oberkörper nach vorn und stehen Sie mit der Kraft der Beine auf, bis Sie aufrecht stehen.","Setzen Sie sich langsam wieder hin, ohne sich fallen zu lassen."],"fehler":["Die Person holt mit dem Oberkörper Schwung.","Die Knie fallen beim Aufstehen nach innen.","Die Person lässt sich auf den Stuhl fallen."]},
{"schluessel":"AF-03","version":"1.0.0","name":"Exzentrisches Hinsetzen","alltagsname":"Langsam hinsetzen, bis 4 zählen","region":"ganzkoerper","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"saetze":3,"wiederholungen":8},"anleitung":["Stellen Sie sich mit dem Rücken vor einen stabilen Stuhl, die Waden berühren fast die Sitzkante.","Strecken Sie die Arme nach vorn und schieben Sie das Gesäß nach hinten.","Setzen Sie sich ganz langsam hin und zählen Sie dabei laut bis 4.","Stehen Sie danach auf, wie es Ihnen leichtfällt, gern auch mit den Händen."],"fehler":["Die Person lässt sich auf den letzten Zentimetern fallen.","Die Knie fallen nach innen.","Die Luft wird angehalten."]},
{"schluessel":"AF-04","version":"1.0.0","name":"Treppensteigen mit Geländer","alltagsname":"Treppe am Geländer steigen","region":"ganzkoerper","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["stufe"],"niveau":2,"dosierung":{"wiederholungen":[1,2],"taeglich":1},"anleitung":["Stellen Sie sich unten an die Treppe und halten Sie sich mit einer Hand am Geländer fest.","Setzen Sie einen Fuß ganz auf die erste Stufe und steigen Sie mit der Kraft dieses Beins hinauf.","Steigen Sie im Wechselschritt weiter und gehen Sie ebenso ruhig wieder hinunter, die Hand immer am Geländer.","Ein Durchgang ist einmal die Treppe hinauf und wieder hinunter; Pausen sind jederzeit erlaubt."],"fehler":["Die Person zieht sich mit dem Arm am Geländer hoch.","Der Fuß steht nur mit der Spitze auf der Stufe.","Beim Hinuntergehen wird gehastet."],"hinweise_praxis":"Zuerst gemeinsam im Hausbesuch üben, mit sicherem Geländer und gutem Licht. Die Zahl der Stufen bei Bedarf als Last in der Dosierung eintragen."},
{"schluessel":"AF-05","version":"1.0.0","name":"Treppensteigen mit Gehstütze, Nachstellschritt","alltagsname":"Treppe mit Stütze im Nachstellschritt","region":"ganzkoerper","ziel":"koordination","ausgangsstellung":"stand","hilfsmittel":["stufe","gehhilfe"],"niveau":1,"dosierung":{"wiederholungen":1,"taeglich":1},"anleitung":["Halten Sie sich mit einer Hand am Geländer fest und nehmen Sie die Gehstütze in die andere Hand.","Hinauf: Setzen Sie zuerst das kräftigere Bein auf die Stufe, dann folgen Stütze und das andere Bein auf dieselbe Stufe.","Hinunter: Setzen Sie zuerst die Stütze und das schwächere Bein eine Stufe tiefer, dann folgt das kräftigere Bein.","Nehmen Sie jede Stufe einzeln und stellen Sie beide Füße nebeneinander, bevor Sie weitergehen."],"fehler":["Die Reihenfolge der Beine wird vertauscht.","Die Stütze steht nur halb auf der Stufe.","Die Person steigt im Wechselschritt statt im Nachstellschritt."],"hinweise_praxis":"Welches Bein wie stark belastet werden darf und ob mit einer oder zwei Stützen, richtet sich nach der ärztlichen Vorgabe. Zuerst gemeinsam im Hausbesuch üben."},
{"schluessel":"AF-06","version":"1.0.0","name":"Aufheben eines Gegenstands mit Abstützen","alltagsname":"Mit Abstützen etwas vom Boden aufheben","region":"lws","ziel":"koordination","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":5,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an eine Arbeitsplatte und legen Sie einen leichten Gegenstand neben Ihren Fuß auf den Boden.","Stützen Sie sich mit einer Hand fest auf der Arbeitsplatte ab.","Beugen Sie Knie und Hüfte und greifen Sie mit der freien Hand den Gegenstand, der Rücken bleibt lang.","Drücken Sie sich mit den Beinen und der stützenden Hand wieder in den Stand."],"fehler":["Der Rücken rundet sich stark, die Knie bleiben gestreckt.","Der Gegenstand liegt zu weit vom Körper entfernt.","Die Person kommt mit Schwung hoch."]},
{"schluessel":"AF-07","version":"1.0.0","name":"Heben aus der Kniebeuge","alltagsname":"Kiste rückengerecht anheben","region":"lws","ziel":"kraft","ausgangsstellung":"stand","hilfsmittel":["alltagsgegenstand"],"niveau":3,"dosierung":{"saetze":3,"wiederholungen":5},"anleitung":["Stellen Sie einen leichten Gegenstand, etwa eine Kiste, eine Tasche oder einen Ball, vor sich auf den Boden und stellen Sie sich hüftbreit nah davor.","Gehen Sie mit geradem Rücken in die Knie und fassen Sie den Gegenstand mit beiden Händen.","Spannen Sie den Bauch an und richten Sie sich mit der Kraft der Beine auf, der Gegenstand bleibt nah am Körper.","Stellen Sie ihn auf demselben Weg wieder ab, ohne den Oberkörper zu drehen."],"fehler":["Der Rücken rundet sich, die Beine bleiben gestreckt.","Der Gegenstand ist weit vom Körper entfernt.","Die Person dreht sich mit der Last."],"hinweise_praxis":"Bei Osteoporose keine belastete, endgradige Beugung der Wirbelsäule. Das Gewicht des Gegenstands als Last in der Dosierung eintragen."},
{"schluessel":"AF-08","version":"1.0.0","name":"Tragen mit beiden Händen (Farmer's Walk)","alltagsname":"Zwei Taschen tragen","region":"ganzkoerper","ziel":"kraft","ausgangsstellung":"gehen","hilfsmittel":["alltagsgegenstand"],"niveau":3,"dosierung":{"saetze":3,"dauer_s":30},"anleitung":["Nehmen Sie in jede Hand eine gleich schwere Tasche, etwa mit Wasserflaschen gefüllt.","Stellen Sie sich aufrecht hin, die Schultern sind locker und tief.","Gehen Sie mit ruhigen Schritten geradeaus, etwa 20 Meter oder so lange, wie es im Plan steht.","Stellen Sie die Taschen mit geradem Rücken aus den Knien ab und machen Sie eine Pause."],"fehler":["Der Oberkörper neigt sich zur Seite.","Die Schultern ziehen nach oben.","Die Schritte werden kurz und unsicher."],"hinweise_praxis":"Das Gewicht der Taschen als Last in der Dosierung eintragen, etwa „je 2 kg“. Nur auf ebenem Weg ohne Stolperfallen."},
{"schluessel":"AF-09","version":"1.0.0","name":"Aufstehen vom Boden mit Stuhl","alltagsname":"Mit Hilfe des Stuhls vom Boden aufstehen","region":"ganzkoerper","ziel":"koordination","ausgangsstellung":"kniestand","hilfsmittel":["stuhl"],"niveau":3,"dosierung":{"wiederholungen":[2,3]},"anleitung":["Drehen Sie sich am Boden auf die Seite und kommen Sie über den Vierfüßlerstand in den Kniestand vor einem stabilen Stuhl oder festen Hocker.","Stützen Sie beide Hände auf die Sitzfläche.","Stellen Sie einen Fuß vor sich auf den Boden, sodass Sie auf einem Knie knien.","Drücken Sie sich mit dem vorderen Bein und den Armen hoch in den Stand.","Drehen Sie sich um und setzen Sie sich darauf, bevor Sie weitergehen."],"fehler":["Stuhl oder Hocker stehen nicht fest und rutschen weg.","Die Person versucht, sich aus der Rückenlage direkt hochzuziehen.","Die Person steht zu schnell auf und bekommt Schwindel."],"hinweise_praxis":"Zuerst gemeinsam im Hausbesuch üben. Den Ablauf für Stürze besprechen (Hausnotruf, Telefon in Reichweite). Ein Kissen unter den Knien schont die Kniescheiben."},
{"schluessel":"AT-01","version":"1.0.0","name":"Zwerchfellatmung","alltagsname":"In den Bauch atmen","region":"rumpf","ziel":"atmung","ausgangsstellung":"rueckenlage","hilfsmittel":["kissen"],"niveau":1,"dosierung":{"wiederholungen":10,"taeglich":3},"anleitung":["Legen Sie sich bequem auf den Rücken, ein Kissen unter dem Kopf, und stellen Sie die Beine an.","Legen Sie eine Hand auf den Bauch und die andere auf die Brust.","Atmen Sie langsam durch die Nase ein, sodass sich die Hand auf dem Bauch hebt und die Hand auf der Brust ruhig bleibt.","Atmen Sie langsam und locker durch den Mund aus, der Bauch senkt sich dabei wieder."],"fehler":["Die Brust und die Schultern heben sich beim Einatmen, der Bauch bleibt flach.","Es wird zu schnell und zu tief geatmet, der Person wird schwindelig.","Der Bauch wird aktiv herausgedrückt, statt sich mit dem Atem zu heben."],"hinweise_praxis":"Wird der Person schwindelig, einige normale Atemzüge einschieben. Später auch im Sitz üben."},
{"schluessel":"AT-02","version":"1.0.0","name":"Lippenbremse","alltagsname":"Durch locker geschlossene Lippen ausatmen","region":"rumpf","ziel":"atmung","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":[5,10]},"anleitung":["Setzen Sie sich bequem hin und lassen Sie die Schultern locker.","Atmen Sie ruhig durch die Nase ein.","Legen Sie die Lippen locker aufeinander und lassen Sie die Luft langsam durch den schmalen Spalt ausströmen, als wollten Sie eine Kerzenflamme nur zum Flackern bringen.","Atmen Sie etwa doppelt so lange aus wie ein und wiederholen Sie das in Ruhe."],"fehler":["Die Wangen blähen sich auf.","Die Luft wird kräftig herausgepresst.","Das Einatmen wird hastig und tief."],"hinweise_praxis":"Bei Bedarf einsetzen, etwa bei Atemnot beim Treppensteigen oder nach Anstrengung; gut kombinierbar mit Kutschersitz und Torwartstellung."},
{"schluessel":"AT-03","version":"1.0.0","name":"Kutschersitz","alltagsname":"Unterarme auf die Oberschenkel stützen","region":"rumpf","ziel":"atmung","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"dauer_s":120},"anleitung":["Setzen Sie sich vorn auf einen stabilen Stuhl und stellen Sie die Füße etwas weiter als hüftbreit auf.","Neigen Sie den Oberkörper nach vorn und legen Sie die Unterarme auf die Oberschenkel.","Lassen Sie Schultern, Nacken und Hände locker.","Atmen Sie ruhig durch die Nase ein und mit der Lippenbremse langsam aus, bis der Atem ruhiger wird."],"fehler":["Die Schultern werden zu den Ohren hochgezogen.","Der Oberkörper sinkt so weit zusammen, dass der Bauch eingeengt wird."],"hinweise_praxis":"Atemerleichternde Stellung, bei Bedarf einzusetzen, etwa nach dem Treppensteigen. Startwert 2 Minuten, üblich sind 1 bis 3 Minuten."},
{"schluessel":"AT-04","version":"1.0.0","name":"Torwartstellung","alltagsname":"Im Stehen auf die Oberschenkel stützen","region":"rumpf","ziel":"atmung","ausgangsstellung":"stand","hilfsmittel":[],"hilfsmittel_optional":["tisch"],"niveau":1,"dosierung":{"dauer_s":120},"anleitung":["Stellen Sie die Füße etwas weiter als hüftbreit auseinander und beugen Sie die Knie leicht.","Neigen Sie den Oberkörper mit geradem Rücken nach vorn und stützen Sie die Hände oberhalb der Knie auf die Oberschenkel.","Alternativ stützen Sie die Unterarme auf eine Arbeitsplatte oder Fensterbank.","Lassen Sie die Schultern locker und atmen Sie ruhig mit der Lippenbremse aus, bis der Atem ruhiger wird."],"fehler":["Die Schultern werden hochgezogen.","Die Knie werden ganz durchgedrückt.","Der Kopf hängt tief, der Rücken wird stark rund."],"hinweise_praxis":"Atemerleichternde Stellung für unterwegs, bei Bedarf einzusetzen. Startwert 2 Minuten, üblich sind 1 bis 3 Minuten."},
{"schluessel":"AT-05","version":"1.0.0","name":"Flankenatmung","alltagsname":"Gegen die Hände in die Seiten atmen","region":"rumpf","ziel":"atmung","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich aufrecht hin, die Füße stehen fest auf dem Boden.","Legen Sie die Hände seitlich an die unteren Rippen, die Daumen zeigen nach hinten.","Atmen Sie langsam durch die Nase ein und lenken Sie den Atem gegen Ihre Hände, sodass sich die Rippen zur Seite weiten.","Atmen Sie langsam mit der Lippenbremse aus und spüren Sie, wie die Rippen wieder nach innen sinken."],"fehler":["Die Schultern heben sich beim Einatmen.","Es wird zu schnell geatmet, der Person wird schwindelig."],"hinweise_praxis":"Ein leichter Druck der Hände zu Beginn der Einatmung gibt eine Rückmeldung; die Fachperson kann die Hände am Anfang selbst anlegen."},
{"schluessel":"AT-06","version":"1.0.0","name":"Atemvertiefung mit Armheben","alltagsname":"Beim Einatmen die Arme heben","region":"rumpf","ziel":"atmung","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Hände liegen auf den Oberschenkeln.","Heben Sie beim Einatmen durch die Nase beide Arme langsam nach vorn und so weit nach oben, wie es angenehm geht.","Senken Sie die Arme beim Ausatmen durch den Mund langsam wieder ab.","Lassen Sie sich Zeit und machen Sie nach jedem Atemzug eine kleine Pause."],"fehler":["Die Arme werden schneller bewegt, als der Atem fließt.","Der Rücken geht beim Armheben ins Hohlkreuz.","Die Schultern werden zu den Ohren hochgezogen."],"hinweise_praxis":"Bei eingeschränkter Schulterbeweglichkeit nur so weit heben, wie es schmerzfrei geht, oder einen Arm nach dem anderen."},
{"schluessel":"AT-07","version":"1.0.0","name":"Halbmond-Dehnlagerung im Sitz","alltagsname":"Seitlich neigen, in die Flanke atmen","region":"rumpf","ziel":"dehnung","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":2,"dosierung":{"wiederholungen":5,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl und stützen Sie eine Hand neben sich auf die Sitzfläche.","Heben Sie den anderen Arm über den Kopf und neigen Sie den Oberkörper langsam zur Seite der stützenden Hand.","Neigen Sie sich nur so weit, bis Sie eine Dehnung in der oberen Flanke spüren.","Atmen Sie in dieser Stellung ruhig und tief in die gedehnte Seite und kommen Sie nach den Atemzügen zur Mitte zurück.","Wechseln Sie danach die Seite."],"fehler":["Der Oberkörper dreht sich nach vorn, statt sich zur Seite zu neigen.","Das Gesäß der gedehnten Seite hebt vom Stuhl ab.","Die Luft wird in der Dehnung angehalten."],"hinweise_praxis":"Bei frischen Narben an Brustkorb oder Bauch die Dehnung nur nach Rücksprache mit der behandelnden Ärztin oder dem Arzt."},
{"schluessel":"AT-08","version":"1.0.0","name":"Huffing (forcierte Exspiration)","alltagsname":"Mit offenem Mund kräftig aushauchen","region":"rumpf","ziel":"atmung","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":[2,3],"taeglich":2},"anleitung":["Setzen Sie sich aufrecht hin und atmen Sie einige Male ruhig ein und aus.","Atmen Sie etwas tiefer als sonst ein.","Hauchen Sie die Luft mit weit geöffnetem Mund kräftig, aber ohne zu pressen aus, als wollten Sie einen Spiegel beschlagen.","Atmen Sie danach wieder einige Male ruhig; löst sich Schleim, husten Sie ihn ab und spucken ihn in ein Taschentuch."],"fehler":["Statt zu hauchen wird gehustet oder gepresst.","Die Pausen mit ruhiger Atmung fehlen, ein Hustenreiz entsteht.","Der Mund ist beim Aushauchen fast geschlossen."],"hinweise_praxis":"Ein Zyklus ist ruhiges Atmen, einige tiefere Atemzüge und ein bis zwei Huffs. Bei Blut im Auswurf, Fieber oder zunehmender Atemnot ärztlich abklären lassen."},
{"schluessel":"AT-09","version":"1.0.0","name":"Schnüffelatmung","alltagsname":"Mehrmals kurz durch die Nase einatmen","region":"rumpf","ziel":"atmung","ausgangsstellung":"sitz","hilfsmittel":[],"niveau":1,"dosierung":{"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich aufrecht hin und atmen Sie zuerst ruhig aus.","Atmen Sie in zwei bis drei kurzen Zügen durch die Nase ein, als würden Sie an einer Blume schnuppern.","Atmen Sie danach langsam mit der Lippenbremse aus.","Machen Sie nach jedem Atemzug eine kleine Pause mit normaler Atmung."],"fehler":["Es wird zu schnell hintereinander geatmet, der Person wird schwindelig.","Die Schultern werden beim Einatmen hochgezogen."],"hinweise_praxis":"Wird der Person schwindelig, die Übung unterbrechen und normal weiteratmen lassen."},
{"schluessel":"AT-10","version":"1.0.0","name":"Ausatmen gegen Widerstand (Strohhalm)","alltagsname":"Durch einen Strohhalm ausatmen","region":"rumpf","ziel":"atmung","ausgangsstellung":"sitz","hilfsmittel":["alltagsgegenstand"],"niveau":2,"dosierung":{"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich aufrecht hin und nehmen Sie einen Strohhalm locker zwischen die Lippen.","Atmen Sie ruhig durch die Nase ein.","Atmen Sie langsam und gleichmäßig durch den Strohhalm aus, ohne die Wangen aufzublasen.","Atmen Sie zwischen den Atemzügen einige Male normal und hören Sie bei Schwindel auf."],"fehler":["Die Wangen blähen sich auf.","Es wird mit viel Kraft gepresst.","Durch den Strohhalm wird auch eingeatmet."],"hinweise_praxis":"Eigenen Strohhalm verwenden, nicht teilen. Ein dünnerer Strohhalm gibt mehr Widerstand."},
{"schluessel":"AT-11","version":"1.0.0","name":"Thoraxrotation mit Atmung","alltagsname":"Beim Ausatmen den Oberkörper drehen","region":"bws","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen Stuhl, die Füße stehen fest und die Arme sind vor der Brust verschränkt.","Atmen Sie durch die Nase ein und machen Sie sich dabei groß.","Drehen Sie beim Ausatmen den Oberkörper langsam zu einer Seite, das Becken bleibt ruhig sitzen.","Kommen Sie beim nächsten Einatmen zur Mitte zurück und drehen Sie beim Ausatmen zur anderen Seite."],"fehler":["Das Becken und die Knie drehen mit.","Die Drehung kommt nur aus dem Kopf.","Die Luft wird angehalten."]},
{"schluessel":"NE-01","version":"1.0.0","name":"Sitzbalance mit Gewichtsverlagerung","alltagsname":"Im Sitz das Gewicht verlagern","region":"rumpf","ziel":"gleichgewicht","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen festen Stuhl ohne Rollen, die Füße stehen hüftbreit und flach auf dem Boden.","Verlagern Sie Ihr Gewicht langsam auf eine Gesäßhälfte, sodass die andere leichter wird; der Kopf bleibt aufrecht.","Kommen Sie zurück in die Mitte und verlagern Sie das Gewicht danach zur anderen Seite.","Bewegen Sie sich nur so weit, wie Sie sicher sitzen, und halten Sie sich bei Unsicherheit am Sitz fest."],"fehler":["Der Oberkörper knickt in der Taille zur Seite ab, statt als Ganzes über die Gesäßhälfte zu wandern.","Der Kopf neigt sich mit, statt aufrecht zu bleiben.","Die Füße heben vom Boden ab.","Die Bewegung wird schnell und schwungvoll."],"hinweise_praxis":"Zu Beginn sichert die Fachperson oder eine angeleitete Person auf der Seite, zu der verlagert wird."},
{"schluessel":"NE-02","version":"1.0.0","name":"Reichen im Sitz in alle Richtungen","alltagsname":"Im Sitz nach Gegenständen greifen","region":"rumpf","ziel":"gleichgewicht","ausgangsstellung":"sitz","hilfsmittel":["stuhl","alltagsgegenstand"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen festen Stuhl, beide Füße stehen flach auf dem Boden.","Greifen Sie mit einer Hand langsam nach einem Gegenstand, etwa einem Becher, der knapp außerhalb Ihrer Reichweite steht.","Greifen Sie ebenso nach vorn, zur Seite und schräg nach vorn, das Gesäß bleibt dabei auf dem Stuhl.","Kommen Sie nach jedem Greifen ganz zurück in den aufrechten Sitz und halten Sie sich bei Unsicherheit mit der anderen Hand am Sitz fest."],"fehler":["Das Gesäß rutscht auf dem Stuhl nach vorn.","Die Füße heben vom Boden ab.","Der Rücken wird rund, statt aus der Hüfte nach vorn zu neigen."],"hinweise_praxis":"Zu Beginn sichert die Fachperson oder eine angeleitete Person auf der Seite, zu der gegriffen wird."},
{"schluessel":"NE-03","version":"1.0.0","name":"Armführung mit gefalteten Händen","alltagsname":"Mit gefalteten Händen die Arme heben","region":"schulter","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl","tisch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich an einen Tisch und falten Sie die Hände so, dass die Finger ineinandergreifen.","Legen Sie die gefalteten Hände vor sich auf den Tisch.","Heben Sie die Arme mit gestreckten Ellbogen langsam nach vorn oben, höchstens bis Schulterhöhe und nur so weit, wie es ohne Schmerz geht.","Senken Sie die Arme langsam wieder auf den Tisch."],"fehler":["Die Schultern werden zu den Ohren hochgezogen.","Der Oberkörper lehnt sich nach hinten, statt die Arme zu heben.","Die Ellbogen knicken ein."],"hinweise_praxis":"Bei schmerzhafter oder instabiler Schulter nur bis Schulterhöhe und ohne Zug am Arm; die Höhe vor Ort festlegen."},
{"schluessel":"NE-04","version":"1.0.0","name":"Tischwischen","alltagsname":"Mit dem Handtuch Kreise auf dem Tisch","region":"schulter","ziel":"koordination","ausgangsstellung":"sitz","hilfsmittel":["stuhl","tisch","handtuch"],"niveau":1,"dosierung":{"saetze":2,"dauer_s":60,"taeglich":1},"anleitung":["Setzen Sie sich an einen Tisch und legen Sie ein Handtuch vor sich.","Legen Sie eine Hand oder beide Hände flach auf das Handtuch.","Wischen Sie langsam große Kreise, erst in die eine, dann in die andere Richtung.","Schieben Sie das Handtuch zwischendurch weit nach vorn und ziehen Sie es wieder zu sich.","Bleiben Sie mit dem Gesäß auf dem Stuhl und machen Sie eine Pause, wenn der Arm müde wird."],"fehler":["Die Schulter wird zum Ohr hochgezogen.","Der Oberkörper macht die Bewegung, der Arm bleibt fast still.","Die Kreise werden klein und hastig."]},
{"schluessel":"NE-05","version":"1.0.0","name":"Becher umsetzen","alltagsname":"Becher greifen und versetzen","region":"hand","ziel":"koordination","ausgangsstellung":"sitz","hilfsmittel":["stuhl","tisch","alltagsgegenstand"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Setzen Sie sich an einen Tisch und stellen Sie einen leeren, unzerbrechlichen Becher vor sich.","Greifen Sie den Becher mit der ganzen Hand und heben Sie ihn ein kleines Stück an.","Setzen Sie ihn eine Handbreit weiter zur Seite ab, lassen Sie los und bringen Sie ihn danach an seinen Platz zurück.","Arbeiten Sie langsam und genau und machen Sie eine Pause, wenn die Hand müde wird."],"fehler":["Die Schulter wird hochgezogen.","Der Oberkörper lehnt sich zum Becher, statt den Arm zu bewegen.","Der Becher wird abgestellt, bevor er ruhig über dem Ziel steht."],"hinweise_praxis":"Steigerung über den Abstand, über Wasser im Becher oder über kleinere Gegenstände."},
{"schluessel":"NE-06","version":"1.0.0","name":"Feinmotorik mit kleinen Gegenständen","alltagsname":"Münzen oder Knöpfe aufheben","region":"hand","ziel":"koordination","ausgangsstellung":"sitz","hilfsmittel":["stuhl","tisch","alltagsgegenstand"],"niveau":2,"dosierung":{"saetze":1,"dauer_s":120,"taeglich":1},"anleitung":["Setzen Sie sich an einen Tisch und legen Sie einige Münzen oder Knöpfe vor sich.","Heben Sie die Gegenstände einzeln mit Daumen und Zeigefinger auf und legen Sie sie in eine Schale.","Nehmen Sie danach Daumen und Mittelfinger, dann Daumen und Ringfinger.","Arbeiten Sie in Ruhe und ohne Zeitdruck."],"fehler":["Die Gegenstände werden über die Tischkante gezogen, statt sie zu greifen.","Die ganze Hand greift statt der Fingerspitzen.","Die Schulter spannt sich an."],"hinweise_praxis":"Kleine Gegenstände nur, wenn kein Risiko besteht, dass sie in den Mund genommen werden; sonst größere wie Wäscheklammern wählen."},
{"schluessel":"NE-07","version":"1.0.0","name":"Zielbewegung des Beins im Sitz","alltagsname":"Mit dem Fuß Markierungen antippen","region":"huefte","ziel":"koordination","ausgangsstellung":"sitz","hilfsmittel":["stuhl","alltagsgegenstand"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen festen Stuhl und legen Sie drei Markierungen vor sich auf den Boden, etwa Bierdeckel.","Tippen Sie mit einem Fuß langsam und genau nacheinander auf jede Markierung.","Stellen Sie den Fuß nach jedem Antippen zurück an seinen Platz.","Wechseln Sie nach allen Wiederholungen das Bein."],"fehler":["Der Fuß wird geschleudert statt geführt.","Der Oberkörper lehnt sich nach hinten.","Die Bewegung wird schnell und ungenau."]},
{"schluessel":"NE-08","version":"1.0.0","name":"Gewichtsübernahme im Stand mit Halt","alltagsname":"Gewicht auf ein Bein bringen","region":"ganzkoerper","ziel":"gleichgewicht","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":1,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":1},"anleitung":["Stellen Sie sich dicht vor die Küchenarbeitsplatte, legen Sie beide Hände darauf und stellen Sie die Füße hüftbreit.","Schieben Sie das Becken langsam zur Seite, bis Ihr Gewicht ganz über einem Bein steht.","Halten Sie die Stellung kurz, das Knie des Standbeins bleibt leicht gebeugt.","Kommen Sie zurück in die Mitte und bringen Sie das Gewicht danach auf das andere Bein."],"fehler":["Der Oberkörper neigt sich zur Seite, statt das Becken über das Bein zu schieben.","Das Knie des Standbeins wird nach hinten durchgedrückt.","Die Hände übernehmen das Gewicht."],"hinweise_praxis":"Zu Beginn gemeinsam üben; Angehörige können beim Hausbesuch angeleitet werden, seitlich zu sichern."},
{"schluessel":"NE-09","version":"1.0.0","name":"Schrittauslösung vor und zurück","alltagsname":"Mit Halt einen Schritt vor und zurück","region":"ganzkoerper","ziel":"koordination","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich seitlich an die Küchenarbeitsplatte, legen Sie eine Hand darauf und räumen Sie den Weg vor sich frei.","Verlagern Sie Ihr Gewicht auf ein Bein und machen Sie mit dem anderen einen deutlichen Schritt nach vorn, die Ferse setzt zuerst auf.","Bringen Sie das Gewicht auf den vorderen Fuß und setzen Sie ihn danach mit einem Schritt wieder zurück.","Wechseln Sie nach allen Wiederholungen das Bein; lautes Mitzählen kann helfen, den Schritt zu starten."],"fehler":["Der Schritt bleibt klein und schlurfend.","Das Gewicht bleibt auf dem hinteren Bein.","Der Oberkörper kippt nach vorn."]},
{"schluessel":"NE-10","version":"1.0.0","name":"Gehen mit großen Schritten und Armschwung","alltagsname":"Große Schritte, Arme mitschwingen","region":"ganzkoerper","ziel":"koordination","ausgangsstellung":"gehen","hilfsmittel":[],"niveau":2,"dosierung":{"saetze":2,"wiederholungen":10,"taeglich":3},"anleitung":["Gehen Sie in einem freien Flur ohne Teppichkanten und andere Stolperfallen.","Machen Sie bewusst große Schritte und setzen Sie zuerst die Ferse auf.","Lassen Sie die Arme kräftig mitschwingen, der rechte Arm geht mit dem linken Bein nach vorn.","Zählen Sie bei Bedarf laut im Takt mit und bleiben Sie stehen, sobald Sie unsicher werden."],"fehler":["Die Schritte werden nach wenigen Metern wieder kleiner.","Die Füße schlurfen über den Boden.","Die Arme hängen still."],"hinweise_praxis":"Takt als Hilfe (laut zählen, Musik). Bei Sturzgefahr zuerst mit Begleitung oder an einer Wand entlang üben."},
{"schluessel":"NE-11","version":"1.0.0","name":"Wenden in großen Schritten","alltagsname":"Sich in großen Schritten umdrehen","region":"ganzkoerper","ziel":"koordination","ausgangsstellung":"stand","hilfsmittel":[],"hilfsmittel_optional":["stuhl"],"niveau":2,"dosierung":{"wiederholungen":5,"je_seite":true,"taeglich":1},"anleitung":["Stellen Sie sich in einen freien Raum ohne Stolperfallen, ein fester Stuhl steht in Reichweite.","Drehen Sie sich in einem großen Bogen mit mehreren deutlichen Schritten um, statt auf der Stelle zu drehen.","Heben Sie die Füße bei jedem Schritt an und zählen Sie bei Bedarf laut mit.","Bleiben Sie nach der Drehung kurz stehen und drehen Sie danach in die andere Richtung."],"fehler":["Die Drehung geschieht auf der Stelle mit kleinen Trippelschritten.","Die Füße überkreuzen sich.","Die Füße bleiben am Boden haften."],"hinweise_praxis":"Bei Sturzgefahr zuerst mit Begleitung üben."},
{"schluessel":"NE-12","version":"1.0.0","name":"Große Streckbewegung im Sitz","alltagsname":"Sich ganz groß machen, Arme weit","region":"ganzkoerper","ziel":"mobilitaet","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"wiederholungen":10,"taeglich":2},"anleitung":["Setzen Sie sich vorn auf einen festen Stuhl, die Füße stehen hüftbreit auf dem Boden.","Strecken Sie die Arme kraftvoll schräg nach oben und zur Seite, öffnen Sie die Hände weit und richten Sie den Oberkörper ganz auf.","Halten Sie diese große Stellung kurz und schauen Sie dabei nach vorn oben.","Lassen Sie die Arme danach locker auf die Oberschenkel sinken."],"fehler":["Die Bewegung bleibt klein und kraftlos.","Der Rücken bleibt rund.","Die Luft wird angehalten."]},
{"schluessel":"AU-01","version":"1.0.0","name":"Gehen in der Wohnung nach Zeit","alltagsname":"In der Wohnung gehen","region":"ganzkoerper","ziel":"ausdauer","ausgangsstellung":"gehen","hilfsmittel":[],"hilfsmittel_optional":["gehhilfe"],"niveau":1,"dosierung":{"dauer_s":300,"taeglich":2},"anleitung":["Räumen Sie Teppichkanten und andere Stolperfallen aus dem Weg und nehmen Sie Ihre Gehhilfe, wenn Sie eine benutzen.","Gehen Sie in ruhigem, gleichmäßigem Tempo durch die Wohnung, etwa vom Flur in die Küche und zurück.","Gehen Sie so zügig, dass Sie dabei noch gut sprechen können.","Gehen Sie so lange, wie es im Plan steht, und setzen Sie sich bei Bedarf zwischendurch hin."],"fehler":["Das Tempo ist so hoch, dass die Person außer Atem kommt.","Der Blick geht dauerhaft auf die Füße, der Oberkörper sinkt nach vorn.","Die Gehhilfe bleibt stehen, obwohl sie sonst gebraucht wird."],"hinweise_praxis":"Intensität so wählen, dass sich die Person dabei noch unterhalten kann. Startwert 5 Minuten; die Dauer bis 10 Minuten im Plan anpassen."},
{"schluessel":"AU-02","version":"1.0.0","name":"Spaziergang mit Zeitsteigerung","alltagsname":"Draußen spazieren gehen","region":"ganzkoerper","ziel":"ausdauer","ausgangsstellung":"gehen","hilfsmittel":[],"hilfsmittel_optional":["gehhilfe"],"niveau":2,"dosierung":{"dauer_s":1200},"anleitung":["Ziehen Sie feste Schuhe an und nehmen Sie Ihre Gehhilfe mit, wenn Sie eine benutzen.","Wählen Sie einen ebenen Weg mit Bänken zum Ausruhen, am besten eine Runde, die Sie kennen.","Gehen Sie zügig, aber so, dass Sie sich dabei noch unterhalten können.","Gehen Sie so lange, wie es im Plan steht, und machen Sie eine Pause, wenn Sie sie brauchen."],"fehler":["Das Tempo ist so hoch, dass die Person außer Atem kommt.","Die Runde ist zu lang für den Rückweg, die Person kommt erschöpft zurück.","Bei Glätte oder Dunkelheit wird trotzdem gegangen."],"hinweise_praxis":"Intensität so wählen, dass sich die Person dabei noch unterhalten kann. Startwert 20 Minuten an etwa fünf Tagen der Woche; die Dauer bis 30 Minuten im Plan anpassen."},
{"schluessel":"AU-03","version":"1.0.0","name":"Marschieren im Sitz","alltagsname":"Im Sitz auf der Stelle marschieren","region":"ganzkoerper","ziel":"ausdauer","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":60,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen stabilen Stuhl, die Füße stehen hüftbreit auf dem Boden.","Heben Sie abwechselnd das rechte und das linke Knie an, als würden Sie im Sitzen gehen.","Schwingen Sie die Arme gegengleich mit und finden Sie einen gleichmäßigen Takt.","Marschieren Sie so lange, wie es im Plan steht, und machen Sie zwischen den Durchgängen eine kurze Pause."],"fehler":["Der Oberkörper lehnt sich nach hinten an die Lehne.","Die Füße heben kaum vom Boden ab.","Die Luft wird angehalten."],"hinweise_praxis":"Intensität so wählen, dass sich die Person dabei noch unterhalten kann. Startwert 1 Minute je Durchgang; bis 2 Minuten im Plan anpassen."},
{"schluessel":"AU-04","version":"1.0.0","name":"Marschieren im Stand mit Halt","alltagsname":"Auf der Stelle marschieren","region":"ganzkoerper","ziel":"ausdauer","ausgangsstellung":"stand","hilfsmittel":["tisch"],"niveau":2,"dosierung":{"saetze":3,"dauer_s":60,"taeglich":1},"anleitung":["Stellen Sie sich vor die Arbeitsplatte und halten Sie sich mit beiden Händen leicht fest.","Heben Sie abwechselnd das rechte und das linke Knie an, als würden Sie auf der Stelle gehen.","Setzen Sie die Füße leise und ganz auf und finden Sie einen gleichmäßigen Takt.","Marschieren Sie so lange, wie es im Plan steht, und machen Sie zwischen den Durchgängen eine kurze Pause."],"fehler":["Die Hände tragen das Gewicht, statt nur Halt zu geben.","Der Oberkörper schwankt zur Seite des Standbeins.","Die Füße werden schwer auf den Boden gestampft."],"hinweise_praxis":"Intensität so wählen, dass sich die Person dabei noch unterhalten kann. Startwert 1 Minute je Durchgang; bis 2 Minuten im Plan anpassen."},
{"schluessel":"AU-05","version":"1.0.0","name":"Bewegungstrainer im Sitz","alltagsname":"Im Sitz am Pedaltrainer radeln","region":"ganzkoerper","ziel":"ausdauer","ausgangsstellung":"sitz","hilfsmittel":["stuhl","pedaltrainer"],"niveau":1,"dosierung":{"dauer_s":600,"taeglich":1},"anleitung":["Stellen Sie den Bewegungstrainer auf eine rutschfeste Unterlage vor einen stabilen Stuhl ohne Rollen.","Setzen Sie sich aufrecht hin und stellen Sie beide Füße auf die Pedale, die Knie sind dabei leicht gebeugt.","Treten Sie in ruhigem, gleichmäßigem Tempo, als würden Sie gemütlich Rad fahren.","Treten Sie so lange, wie es im Plan steht, und lassen Sie die Bewegung am Ende langsam auslaufen."],"fehler":["Der Stuhl steht zu weit weg, die Knie werden ganz durchgestreckt.","Der Widerstand ist so hoch, dass die Person außer Atem kommt.","Der Oberkörper rutscht nach hinten in die Lehne."],"hinweise_praxis":"Intensität so wählen, dass sich die Person dabei noch unterhalten kann. Startwert 10 Minuten; bis 20 Minuten im Plan anpassen. Den Widerstand des Geräts bei Bedarf als Last eintragen."},
{"schluessel":"AU-06","version":"1.0.0","name":"Treppensteigen als Ausdauertraining","alltagsname":"Mehrere Etagen steigen","region":"ganzkoerper","ziel":"ausdauer","ausgangsstellung":"stand","hilfsmittel":["stufe"],"niveau":3,"dosierung":{"wiederholungen":[2,4]},"anleitung":["Stellen Sie sich unten an die Treppe und halten Sie sich mit einer Hand am Geländer fest.","Steigen Sie im Wechselschritt in ruhigem, gleichmäßigem Tempo eine Etage hinauf.","Gehen Sie ebenso ruhig wieder hinunter, die Hand bleibt am Geländer.","Jede Wiederholung ist eine Etage hinauf und wieder hinunter; machen Sie Pausen, wann immer Sie sie brauchen."],"fehler":["Das Tempo ist so hoch, dass die Person oben außer Atem ankommt.","Die Person zieht sich mit dem Arm am Geländer hoch.","Beim Hinuntergehen wird gehastet."],"hinweise_praxis":"Intensität so wählen, dass sich die Person dabei noch unterhalten kann. Zuerst gemeinsam im Hausbesuch üben, mit sicherem Geländer und gutem Licht."},
{"schluessel":"AU-07","version":"1.0.0","name":"Boxen im Sitz","alltagsname":"Im Sitz in die Luft boxen","region":"schulter","ziel":"ausdauer","ausgangsstellung":"sitz","hilfsmittel":["stuhl"],"niveau":1,"dosierung":{"saetze":3,"dauer_s":30,"taeglich":1},"anleitung":["Setzen Sie sich aufrecht auf einen stabilen Stuhl, die Füße stehen fest auf dem Boden.","Ballen Sie locker die Fäuste und halten Sie sie vor die Brust.","Boxen Sie abwechselnd mit der rechten und der linken Faust nach vorn in die Luft und ziehen Sie die Faust jedes Mal zurück.","Boxen Sie in gleichmäßigem Takt so lange, wie es im Plan steht, und atmen Sie dabei weiter."],"fehler":["Der Ellbogen wird ruckartig ganz durchgestreckt.","Der Oberkörper schaukelt mit, statt aufrecht zu bleiben.","Die Luft wird angehalten."],"hinweise_praxis":"Startwert 30 Sekunden je Durchgang; bis 60 Sekunden im Plan anpassen."}
]$katalog$::jsonb,
